window.WORD_MNEMONICS_DB = window.WORD_MNEMONICS_DB || {};
Object.assign(window.WORD_MNEMONICS_DB, {
  "i": "幽默諧音法：「愛呀」\n\n發音聯想：I [aɪ] 唸起來就像「愛呀」。\n\n記憶畫面：腦海浮現「愛呀」的情境——我大聲說出我愛我自己，展現無比自信的態度，展現出我 (I) 的畫面！",
  "ice": "幽默諧音法：「愛絲」\n\n發音聯想：ice 唸起來清涼暢快，像酷暑三十五度下午走進冰店點一碗淋上芒果與煉乳的「愛絲」綿綿冰！\n\n記憶畫面：盛夏體育課剛跑完步，大家衝進甜品店各點一碗透心涼的剉冰加上脆冰塊，「愛絲」這口冰涼感覺真是完美的冰塊冰鎮 (ice)！",
  "ice-cold": "幽默諧音法：「愛斯」\n\n發音聯想：ice-cold [aɪs kold] 唸起來就像「愛斯」。\n\n記憶畫面：這杯飲料冰到愛斯人，喝一口全身都冷了，展現出「冰冷的」 (ice-cold) 的畫面！",
  "iceberg": "字根幽默拆解法：ice（大塊冰塊）＋ berg（高高海上冰山）\n\n構造聯想：iceberg 就是海面上只露出一小角、水面下卻藏著超大「大塊冰塊」的「海上冰山」。\n\n記憶畫面：北極企鵝站在海面那座尖尖「海上冰山」曬太陽，殊不知水底下的「大塊冰塊」體積大上十倍呢，這座海上巨無霸正是冰山浮冰 (iceberg)！",
  "icebox": "字根幽默拆解法：ice（冰） ＋ box（箱子）\n\n構造聯想：由名詞 ice 與 box 複合而成的合成字，現代通常直接用 refrigerator。\n\n記憶畫面：以前沒有插電冷氣時，家裡是用裝滿冰塊的箱子來冰鎮食物，展現出「冷藏庫」 (icebox) 的畫面！",
  "icon": "幽默諧音法：「愛看」\n\n發音聯想：icon [ˋaɪkɑn] 唸起來就像「愛看」。\n\n記憶畫面：電腦桌面上有很多圖示 (icon)，每一個都讓人愛看。",
  "icy": "字根幽默拆解法：ice（冰塊）＋ y（像……一樣冷冰冰的）\n\n構造聯想：icy 就是寒流來襲時碰一下鐵門把手「像」「冰塊」「一樣冷冰冰的」透心涼感。\n\n記憶畫面：冬天凌晨踢掉被子伸腳去碰地板瞬間彈起來，地板簡直「像」「冰塊」「一樣冷冰冰的」，別人眼神臭臭的也可以這樣說，表示冰冷的與冷漠的 (icy)！",
  "idea": "幽默諧音法：「愛弟阿」\n\n發音聯想：idea [aɪˋdiə] 唸起來就像「愛弟阿」。\n\n記憶畫面：聽到一聲「愛弟阿」，就看到企劃會議上他靈機一動提出這個超棒的愛點兒，真是個絕妙的好主意與想法 (idea)！",
  "ideal": "幽默諧音法：「愛弟喔」\n\n發音聯想：ideal [aɪˋdil] 唸起來就像真心稱讚「愛弟喔」。\n\n記憶畫面：相親現場大家都稱讚他個性體貼又誠懇，簡直是心目中「愛弟喔」等級的最佳人選，完全符合理想的 (ideal) 條件！",
  "idealize": "字根幽默拆解法：ideal（理想的） ＋ ize（使化）\n\n構造聯想：將 ideal（理想的） ＋ ize（使化） 結合在一起，就能輕鬆推導出「形成理想」的意思。\n\n記憶畫面：他把愛情理想化 (idealize) 了，覺得愛到低聲下氣也無所謂。",
  "identical": "幽默諧音法：「愛等替卡」\n\n發音聯想：identical [aɪˋdɛntɪkəl] 唸起來就像「愛等替卡」。\n\n記憶畫面：腦海浮現「愛等替卡」的情境——雙胞胎穿著愛的呆踢可（T-shirt），長得完全相同 (identical)。",
  "identification": "幽默諧音法：「愛等塔發客」\n\n發音聯想：identification [aɪ͵dɛntəfəˋkeʃən] 唸起來就像「愛等塔發客」。\n\n記憶畫面：順著「愛等塔發客」的諧音去想：進出公司大樓必須出示身分證件進行識別 (identification) 與確認。",
  "identified": "字根幽默拆解法：identify（確認） ＋ ed（過去分詞或形容詞）\n\n構造聯想：將 identify（確認） ＋ ed（過去分詞或形容詞） 結合在一起，就能輕鬆推導出「被識別的」的意思。\n\n記憶畫面：從「確認」的概念延伸，警察在現場鑑定 (identified) 指紋，終於識別出嫌犯，大喊：我愛燈提法愛得（識別出他了）。",
  "identify": "幽默諧音法：「愛等塔發」\n\n發音聯想：identify [aɪˋdɛntə͵faɪ] 唸起來就像「愛等塔發」。\n\n記憶畫面：聯想到「愛等塔發」的畫面：警察透過指紋認出嫌犯，終於確認 (identify) 了他的身份。",
  "identity": "幽默諧音法：「愛等替替」\n\n發音聯想：identity [aɪˋdɛntɪ͵ti] 唸起來就像「愛等替替」。\n\n記憶畫面：順著「愛等替替」的諧音去想：愛的登低代表爬山登頂時要證明自己的身分 (identity) 與個人特色！",
  "idiom": "幽默諧音法：「伊弟安」\n\n發音聯想：idiom [ˋɪdiəm] 唸起來就像「伊弟安」。\n\n記憶畫面：順著「伊弟安」的諧音去想：台灣阿嬤講話很有地方俗語的味道，這就是有趣的成語 (idiom)。",
  "idiomatic": "字根幽默拆解法：idiom（慣用語） ＋ atic（形容詞）\n\n構造聯想：idiom 指特定語言的習慣用法。\n\n記憶畫面：外國人說出地道的俚語，聽起來非常自然地道的 (idiomatic)，就像母語人士一樣自然。",
  "idiot": "幽默諧音法：「一跌的」\n\n發音聯想：idiot 唸快一點有點像不小心左腳絆右腳「一跌的」迷糊蛋。\n\n記憶畫面：眼鏡架在額頭上還滿屋子急著找眼鏡，最後左腳勾右腳原地摔個軟坐墊，自己也笑說這個「一」「跌」「的」小動作真是傻乎乎可愛迷糊笨蛋 (idiot)！",
  "idiotic": "字根幽默拆解法：idiot（呆萌迷糊蛋）＋ ic（超級像……的）\n\n構造聯想：idiotic 就是做了一件自己都忍不住拍額頭覺得「超級像」「呆萌迷糊蛋」「的」傻萌行為。\n\n記憶畫面：把手機放進冰箱、拿著牛奶瓶走去書桌準備插充電線，這種忙到頭昏簡直「超級像」「呆萌迷糊蛋」「的」烏龍舉動真的太愚笨傻氣般的 (idiotic) 搞笑！",
  "idle": "幽默諧音法：「愛達喔」\n\n發音聯想：idle [ˋaɪdəl] 唸起來就像「愛達喔」。\n\n記憶畫面：順著「愛達喔」的諧音去想：追星族愛的偶像偶像今天不用上班，正無所事事 (idle) 地閒晃。",
  "idol": "幽默諧音法：「愛達喔」\n\n發音聯想：idol [ˋaɪdəl] 唸起來就像「愛達喔」。\n\n記憶畫面：聯想到「愛達喔」的畫面：年輕人都愛追韓團偶像 (idol)，老人家則愛逗孫子開心。",
  "idolize": "字根幽默拆解法：idol（閃耀大偶像）＋ ize（當成心頭寶去崇拜）\n\n構造聯想：idolize 就是把牆上的明星海報「閃耀大偶像」「當成心頭寶去崇拜」每天看十遍。\n\n記憶畫面：房間貼滿歌手簽名海報、手燈買五支、手機桌面全是大頭照，簡直把心中那位「閃耀大偶像」「當成心頭寶去崇拜」到了極點，這就叫做崇拜偶像極端崇拜 (idolize)！",
  "if": "幽默諧音法：「一福」\n\n發音聯想：if [ɪf] 唸起來像如果多「一福」氣。\n\n記憶畫面：如果與假如 (if) 明天陽光放晴再多添「一福」好運，我們就去山頂露營！",
  "ignite": "幽默諧音法：「一蓋特」\n\n發音聯想：ignite [͵ɪɡˋnaɪt] 唸起來就像「一蓋特」。\n\n記憶畫面：打火機一蓋特（蓋上特快點火），火苗瞬間竄起，展現出「點燃」 (ignite) 的畫面！",
  "ignition": "幽默諧音法：「一蓋神」\n\n發音聯想：ignition [͵ɪɡˋnɪʃən] 唸起來就像「一蓋神」。\n\n記憶畫面：汽車鑰匙一轉，引擎啟動的點火裝置 (ignition)像神一樣運作起來。",
  "ignominy": "幽默諧音法：「一格迷你」\n\n發音聯想：ignominy [ˋɪɡnəmɪni] 唸起來就像「一格迷你」。\n\n記憶畫面：因為犯錯被關進一格超小的牢房，連個迷你空間都沒有，感到極度恥辱，展現出「<正式>恥辱」 (ignominy) 的畫面！",
  "ignorance": "字根幽默拆解法：ignore（完全不理會沒學過）＋ ance（狀態）\n\n構造聯想：ignorance 就是從來沒翻開課本「完全不理會沒學過」，一問三不知的空白「狀態」。\n\n記憶畫面：以為水果店賣的紅龍果長在高高的樹上，還一臉認真問朋友怎麼採摘，這種「完全不理會沒學過」的搞笑空白「狀態」就是無知不學無術 (ignorance)！",
  "ignorant": "幽默諧音法：「一根爛的」\n\n發音聯想：ignorant [ˋɪɡnɚənt] 唸起來就像「一根爛的」。\n\n記憶畫面：「一根爛的」腦袋瓜像一根爛掉的木頭，形容對事情完全無知 (ignorant)。",
  "ignore": "幽默諧音法：「一狗」\n\n發音聯想：ignore [͵ɪɡˋnɔr] 唸起來就像「一狗」。\n\n記憶畫面：「一狗」在打架，旁邊的人都裝作沒看見，選擇直接忽視 (ignore)。",
  "ill": "幽默諧音法：「伊喔」\n\n發音聯想：ill [ɪl] 唸起來就像「伊喔」。\n\n記憶畫面：腦海浮現「伊喔」的情境——感冒發燒時全身骨頭硬梆梆、很不舒服 (ill)。",
  "ill-advised": "字根幽默拆解法：ill（壞的） ＋ advised（被建議的）\n\n構造聯想：ill 常見於負面形容詞，advised 來自 advice。\n\n記憶畫面：因為聽信了壞的建議，導致投資慘賠，這真是個不明智的 (ill-advised)決定。",
  "illegal": "字根幽默拆解法：il（否定） ＋ legal（合法的）\n\n構造聯想：il 是 in 的變體，接在 l 開頭的字前表示否定。\n\n記憶畫面：從「否定」的概念延伸，警方嚴厲取締街頭的違規擺攤與違法 (illegal)行為。",
  "illegitimate": "字根幽默拆解法：il（不） ＋ legitimate（正當的）\n\n構造聯想：將 il（不） ＋ legitimate（正當的） 結合在一起，就能輕鬆推導出「私生的」的意思。\n\n記憶畫面：古裝劇中大戶人家爭產，私生 (illegitimate) 子因為身份不合規定而被排除在族譜之外。",
  "illicit": "幽默諧音法：「伊利沙特」\n\n發音聯想：illicit [͵ɪlˋɪsət] 唸起來就像「伊利沙特」。\n\n記憶畫面：順著「伊利沙特」的諧音去想：走私集團把不法的 (illicit) 違禁品私藏在一粒巨大西瓜裡面企圖闖關。",
  "illiteracy": "字根幽默拆解法：il（不） ＋ literacy（識字能力）\n\n構造聯想：literate 是識字的，加上字首 il 表示否定。\n\n記憶畫面：因為不識字 (illiteracy)，他在簽合約時被騙得團團轉，這就是文盲的悲哀。",
  "illness": "幽默諧音法：「一勒斯」\n\n發音聯想：illness [ˋɪlnəs] 唸起來就像「一勒斯」。\n\n記憶畫面：生病了身體一勒一勒的痛，好像快被病魔勒斯一樣，展現出「患病」 (illness) 的畫面！",
  "illogical": "字根幽默拆解法：il（不） ＋ logical（合邏輯的）\n\n構造聯想：logic 是邏輯，加上 al 變成形容詞，再加 il 否定。\n\n記憶畫面：他提出的計畫完全不合常理，簡直是不合邏輯的 (illogical)空想。",
  "illuminate": "幽默諧音法：「伊路蜜泥特」\n\n發音聯想：illuminate [͵ɪlˋumɪnɪt] 唸起來就像「伊路蜜泥特」。\n\n記憶畫面：聯想到「伊路蜜泥特」的畫面：衣服上露出一盞迷妳燈，瞬間照亮 (illuminate) 整個暗暗的房間。",
  "illusion": "幽默諧音法：「伊路然」\n\n發音聯想：illusion [͵ɪlˋuʒən] 唸起來就像「伊路然」。\n\n記憶畫面：聽到一聲「伊路然」，就看到魔術師一揮手把美女一擄秀啦變不見，觀眾眼前看到的只是一場美麗的錯覺 (illusion) 與幻象。",
  "illustrate": "字根幽默拆解法：il（點亮看清楚）＋ lustr（放光明亮）＋ ate（畫出來解釋）\n\n構造聯想：illustrate 就是怕文字太抽象看不懂，乾脆「點亮」「放光明亮」「畫出來解釋」配上小插圖。\n\n記憶畫面：數學應用題看了三遍還是霧煞煞，老師直接拿彩色粉筆把蘋果跟火車圖案「點亮」「放光明亮」「畫出來解釋」，一秒秒懂這就叫說明闡明加插圖於 (illustrate)！",
  "illustration": "字根幽默拆解法：illustrate（說明） ＋ tion（動作或狀態）\n\n構造聯想：將 illustrate（說明） ＋ tion（動作或狀態） 結合在一起，就能輕鬆推導出「插圖」的意思。\n\n記憶畫面：教科書裡精美的插圖 (illustration) 讓枯燥的課文變得生動易懂。",
  "illustrative": "字根幽默拆解法：illustrate（說明） ＋ ive（形容詞）\n\n構造聯想：illustrate 原意為照亮，引申為闡明。\n\n記憶畫面：這張圖表具有作例證用的 (illustrative) 的功能，能解釋複雜的數據。",
  "image": "幽默諧音法：「一妹居」\n\n發音聯想：image [ˋɪmədʒ] 唸起來就像「一妹居」。\n\n記憶畫面：「一妹居」代表手機相簿裡永遠住著「一個正妹的影像 (image)」！",
  "imaginable": "字根幽默拆解法：imagine（想像） ＋ able（能夠的）\n\n構造聯想：將 imagine（想像） ＋ able（能夠的） 結合在一起，就能輕鬆推導出「能想像的」的意思。\n\n記憶畫面：只要人類腦洞夠大，一秒極限能跑的畫面都是可想像的，展現出能想像的 (imaginable) 的畫面！",
  "imaginary": "字根幽默拆解法：imagine（想像） ＋ ary（的）\n\n構造聯想：將 imagine（想像） ＋ ary（的） 結合在一起，就能輕鬆推導出「虛構的」的意思。\n\n記憶畫面：漫畫裡的怪獸一秒夾妳肉，全都是虛構 (imaginary) 幻想出來的。",
  "imagination": "字根幽默拆解法：imagine（想像） ＋ ation（動作或過程）\n\n構造聯想：將 imagine（想像） ＋ ation（動作或過程） 結合在一起，就能輕鬆推導出「想像力」的意思。\n\n記憶畫面：一妹居內喜休形容有豐富想像力 (imagination) 的人，腦中隨時在演內心戲！",
  "imaginative": "字根幽默拆解法：imagination（想像力） ＋ ive（有傾向的）\n\n構造聯想：將 imagination（想像力） ＋ ive（有傾向的） 結合在一起，就能輕鬆推導出「虛構的」的意思。\n\n記憶畫面：一秒夾妳耐踢夫設計師頭腦動很快，充滿富於想像力的創新 (imaginative) 點子。",
  "imagine": "幽默諧音法：「伊賣真」\n\n發音聯想：imagine [͵ɪmˋædʒən] 唸起來就像「伊賣真」。\n\n記憶畫面：順著「伊賣真」的諧音去想：買就準地在腦海中想像 (imagine) 自己中頭獎的畫面。",
  "imitate": "幽默諧音法：「一米特的」\n\n發音聯想：imitate [ˋɪmə͵tet] 唸起來就像「一米特的」。\n\n記憶畫面：身高只有「一米特」的小朋友，學大人走路的樣子超級會「模仿 (imitate)」。",
  "imitation": "字根幽默拆解法：imitate（模仿） ＋ tion（動作或狀態）\n\n構造聯想：將 imitate（模仿） ＋ tion（動作或狀態） 結合在一起，就能輕鬆推導出「模仿」的意思。\n\n記憶畫面：這碗仿造 (imitation) 的塑膠拉麵看起來像真的一樣，其實只是一米湯填出來的模型。",
  "immaculate": "字根幽默拆解法：im（不） ＋ maculate（污點）\n\n構造聯想：字根 macula 是斑點的意思，加上否定字首 im，就是無斑點的。\n\n記憶畫面：這件襯衫洗得一塵不染，完全沒有污點，看起來非常完美 (immaculate)。",
  "immature": "字根幽默拆解法：im（不） ＋ mature（成熟的）\n\n構造聯想：mature 是成熟，im 是常見的否定字首。\n\n記憶畫面：都幾歲了還在玩泥巴，真是個不成熟的 (immature)幼稚怪。",
  "immediate": "字根幽默拆解法：im（不） ＋ mediate（調停解決）\n\n構造聯想：將 im（不） ＋ mediate（調停解決） 結合在一起，就能輕鬆推導出「即刻的」的意思。\n\n記憶畫面：哨聲一響，一秒召喚出得力助手救援，展現立刻的 (immediate) 超高效率！",
  "immediately": "幽默諧音法：「一咪底亞力」\n\n發音聯想：immediately [͵ɪmˋi͵diətli] 唸起來就像「一咪底亞力」。\n\n記憶畫面：老闆一聲令下，他馬上 (immediately)（一咪底亞力）衝去執行任務。",
  "immense": "幽默諧音法：「硬悶斯」\n\n發音聯想：immense [͵ɪmˋɛns] 唸起來就像「硬悶斯」。\n\n記憶畫面：一棟巨大 (immense)無比的鋼筋水泥建築，硬生生地把四周的陽光都擋住悶斯人。",
  "immensity": "幽默諧音法：「音門希替」\n\n發音聯想：immensity [ɪˋmensəti] 唸起來就像「音門希替」。\n\n記憶畫面：站在宇宙的巨大 (immensity)空間前，連聲音（im）都傳不到門（men）口，稀（si）奇的替（ty）換了原本的寂靜。",
  "immigrant": "幽默諧音法：「一根來」\n\n發音聯想：immigrant [ˋɪməɡrənt] 唸起來就像「一根來」。\n\n記憶畫面：新移民 (immigrant)帶著一箱行李來到台灣落地生根，展開新生活。",
  "immigrate": "幽默諧音法：「一米格瑞特」\n\n發音聯想：immigrate [ˋɪmə͵ɡret] 唸起來就像「一米格瑞特」。\n\n記憶畫面：老張帶著全家跨越「一米」的國界線，「移居 (immigrate)」到美國展開新生活。",
  "immigration": "字根幽默拆解法：im（搬進去）＋ migr（大遷徙）＋ ation（名詞）\n\n構造聯想：immigration 就是打包家當「搬進去」別國展開「大遷徙」。\n\n記憶畫面：決定換個國家生活後，全家拖著十個大行李箱準備「搬進去」新家園展開「大遷徙」，這趟跨海定居就叫移民移居 (immigration)！",
  "immobile": "字根幽默拆解法：im（不） ＋ mobile（可移動的）\n\n構造聯想：mobile 是手機或可移動的，im 是否定。\n\n記憶畫面：從「可移」的概念延伸，車子拋錨在路中間，完全不能動 (immobile)，造成大塞車。",
  "immovable": "字根幽默拆解法：im（不） ＋ movable（可移動的）\n\n構造聯想：字首 im 代表否定，movable 來自 move。\n\n記憶畫面：這塊巨石重到完全不動的 (immovable)，推土機來了也動不了。",
  "immune": "幽默諧音法：「已謀」\n\n發音聯想：immune [͵ɪˋmjun] 唸起來就像「已謀」。\n\n記憶畫面：罪犯早已謀劃好退路，成功在法律漏洞中免於 (immune)刑責，不受影響。",
  "immunity": "字根幽默拆解法：immune（免疫的） ＋ ity（性質）\n\n構造聯想：將 immune（免疫的） ＋ ity（性質） 結合在一起，就能輕鬆推導出「免疫力」的意思。\n\n記憶畫面：身體有了免疫力 (immunity)，就像是一層防護罩，讓病毒這些髒東西無法入侵，身體乾淨無泥。",
  "imp": "幽默諧音法：「硬皮」\n\n發音聯想：imp 唸起來小小短促像個調皮「硬皮」小頑童。\n\n記憶畫面：幼稚園裡有個臉皮超「硬」「皮」愛作弄人的小可愛，剛把同學的彩色筆偷偷換位置又笑嘻嘻跑去藏起來，正是人小主意多的小淘氣頑童 (imp)！",
  "impact": "幽默諧音法：「硬背客」\n\n發音聯想：impact [͵ɪmˋpækt] 唸起來就像「硬背客」。\n\n記憶畫面：「硬背客」的行李太重，重重地撞擊機場地磅產生強大影響 (impact)。",
  "impair": "幽默諧音法：「硬陪兒」\n\n發音聯想：impair [͵ɪmˋpɛr] 唸起來就像「硬陪兒」。\n\n記憶畫面：熬夜打電動硬陪兒 (impair) 子，結果視力嚴重受損、視力被損害了。",
  "impartial": "字根幽默拆解法：im（不） ＋ partial（偏心的）\n\n構造聯想：partial 來自 part（部分），只偏向一部分就是偏心。\n\n記憶畫面：法官必須公正，不能對任何一方偏心，這才是公正的 (impartial)審判。",
  "impartiality": "字根幽默拆解法：im（不） ＋ partial（偏袒） ＋ ity（名詞）\n\n構造聯想：partial 是部分的，impartial 就是不偏向任何一部分。\n\n記憶畫面：法官必須保持絕對的公正 (impartiality)，不能對任何一方有偏見。",
  "imparting": "字根幽默拆解法：im（進入） ＋ part（部分）\n\n構造聯想：impart 意為分給一部分，引申為傳授。\n\n記憶畫面：老師把知識的一部分傳授 (imparting)給學生。",
  "impatient": "字根幽默拆解法：im（不） ＋ patient（有耐心的）\n\n構造聯想：patient 既是病人也是有耐心的，im 是否定。\n\n記憶畫面：排隊排太久，他變得非常沒耐心 (impatient)，一直看手錶。",
  "impeccable": "幽默諧音法：「印配可波」\n\n發音聯想：impeccable [͵ɪmˋpɛkəbəl] 唸起來就像「印配可波」。\n\n記憶畫面：這件衣服的剪裁完美無瑕，印上去的圖案配得剛剛好，簡直無懈可擊 (impeccable)。",
  "impeccably": "幽默諧音法：「硬配卡不理」\n\n發音聯想：impeccably [ɪmˋpekəbli] 唸起來就像「硬配卡不理」。\n\n記憶畫面：他穿著一套硬配的西裝，看起來完美無瑕，簡直是無可挑剔地 (impeccably)。",
  "impede": "幽默諧音法：「硬皮的」\n\n發音聯想：impede [͵ɪmˋpid] 唸起來就像「硬皮的」。\n\n記憶畫面：路上有一塊硬皮的石頭擋路，嚴重妨礙 (impede)了交通。",
  "impediment": "字根幽默拆解法：im（進入） ＋ ped（腳）\n\n構造聯想：字根 ped 代表腳，想像腳被絆住的畫面。\n\n記憶畫面：從「進入」的概念延伸，腳被東西絆住，走路一跛一跛的，這就是一種身體上的障礙 (impediment)。",
  "imperative": "幽默諧音法：「硬配蕊替服」\n\n發音聯想：imperative [͵ɪmˋpɛrətɪv] 唸起來就像「硬配蕊替服」。\n\n記憶畫面：上司下達「硬配蕊替服」的拚命令，這是一項極重要 (imperative)且刻不容緩的強制任務，大家必須立刻執行。",
  "imperceptible": "幽默諧音法：「硬怕誰普特波」\n\n發音聯想：imperceptible [͵ɪmpərˋseptəbl] 唸起來就像「硬怕誰普特波」。\n\n記憶畫面：這東西細微到硬是怕誰碰它，因為一碰就碎，根本感覺不到 (imperceptible)它的存在。",
  "imperfectly": "幽默諧音法：「伊姆婆菲可」\n\n發音聯想：imperfectly [ɪmˋpɝfɪktli] 唸起來就像「伊姆婆菲可」。\n\n記憶畫面：聯想到「伊姆婆菲可」的畫面：照片拍出來有瑕疵，帶著不完美地 (imperfectly) 呈現出來。",
  "imperial": "幽默諧音法：「硬配理歐」\n\n發音聯想：imperial [͵ɪmˋpɪriəl] 唸起來就像「硬配理歐」。\n\n記憶畫面：古代皇帝硬要把皇位配給理歐王子，展現出至高無上的帝國 (imperial)權威。",
  "imperturbable": "幽默諧音法：「硬怕特波」\n\n發音聯想：imperturbable [͵ɪmpərˋtɝbəb(ə)l] 唸起來就像「硬怕特波」。\n\n記憶畫面：面對強敵，他依然冷靜 (imperturbable)，就算對方硬是要怕特波（挑釁）他，他也能泰然自若。",
  "implausibility": "字根幽默拆解法：im（不） ＋ plaus（鼓掌合理）\n\n構造聯想：字根 plaus-（鼓掌/合理），plausible 就是合理的，加上 im- 變成相反詞。\n\n記憶畫面：這個故事的難以相信 (implausibility) 太高了，根本沒人會相信主角能單槍匹馬打敗軍隊。",
  "implement": "幽默諧音法：「硬補樂悶」\n\n發音聯想：implement [ˋɪmpləmənt] 唸起來就像「硬補樂悶」。\n\n記憶畫面：為了讓計畫順利進行，「硬補樂悶（把悶氣補齊）」去執行 (implement)與貫徹各項政策工具。",
  "implementation": "字根幽默拆解法：im（進入） ＋ plement（填滿）\n\n構造聯想：implement 是動詞，源自拉丁語，意為填滿或履行。\n\n記憶畫面：從「進入」的概念延伸，為了讓計畫成功，我們硬是把所有細節都補滿並執行 (implementation)到位。",
  "implication": "幽默諧音法：「硬撲累客深」\n\n發音聯想：implication [͵ɪmpləˋkeʃən] 唸起來就像「硬撲累客深」。\n\n記憶畫面：老闆說話「硬撲累客深（話中有話很深奧）」，每一個字背後都有深刻的含意 (implication)與言外之意。",
  "implicit": "幽默諧音法：「硬背麗詩」\n\n發音聯想：implicit [͵ɪmˋplɪsət] 唸起來就像「硬背麗詩」。\n\n記憶畫面：老師沒有明說，但意思硬背麗詩就能懂，這是一種不言明的 (implicit)含蓄暗示。",
  "imply": "幽默諧音法：「因拍來」\n\n發音聯想：imply [͵ɪmˋplaɪ] 唸起來就像「因拍來」。\n\n記憶畫面：老闆講話「因」為「拍」手拍得太大力，反而「暗示 (imply)」了大家年終獎金不多。",
  "impolite": "字根幽默拆解法：im（不） ＋ polite（有禮貌的）\n\n構造聯想：polite 是禮貌，im 是否定字首。\n\n記憶畫面：從「有禮」的概念延伸，對長輩大吼大叫是非常失禮的 (impolite)行為，大家都皺起眉頭。",
  "import": "字根幽默拆解法：im（不） ＋ port（港）\n\n構造聯想：將 im（不） ＋ port（港） 結合在一起，就能輕鬆推導出「進口」的意思。\n\n記憶畫面：因撲滿所以要從國外進口 (import) 大量撲滿商品來賣！",
  "importance": "字根幽默拆解法：im（進入） ＋ portant（重要）\n\n構造聯想：由重要形容詞 important 轉變而來的抽象名詞，字尾 ant 變 ance。\n\n記憶畫面：主管強調這個專案的重要性 (importance)，大家必須全神貫注。",
  "important": "字根幽默拆解法：import（進口） ＋ ant（螞蟻）\n\n構造聯想：將 import（進口） ＋ ant（螞蟻） 結合在一起，就能輕鬆推導出「重要的」的意思。\n\n記憶畫面：老師特別叮嚀這幾個核心觀念超重要 (important)，一定要印寶典筆記裡熟記！",
  "imported": "字根幽默拆解法：port（港口） ＋ im（進入）\n\n構造聯想：字根 port 是港口，im 是進入，貨物進入港口就是進口。\n\n記憶畫面：從「港口」的概念延伸，海關人員檢查貨櫃，發現這批音響設備是從國外運來的進口 (imported)貨。",
  "impose": "字根幽默拆解法：im（不） ＋ pose（姿勢）\n\n構造聯想：將 im（不） ＋ pose（姿勢） 結合在一起，就能輕鬆推導出「徵」的意思。\n\n記憶畫面：硬破茲政府硬破茲破產的決心去徵新稅收，展現出徵 (impose) 的畫面！",
  "imposing": "幽默諧音法：「硬潑森」\n\n發音聯想：imposing [͵ɪmˋpozɪŋ] 唸起來就像「硬潑森」。\n\n記憶畫面：這棟建築物外觀氣勢宏偉 (imposing)，像是有巨人硬潑森（生）氣的壓迫感。",
  "imposition": "字根幽默拆解法：im（進入） ＋ position（位置）\n\n構造聯想：im- 表示進入或向內，position 是位置，強行放入某個位置即為實施或強加。\n\n記憶畫面：從「進入」的概念延伸，政府硬是把一項不合理的稅收強加在人民頭上，就像強行擺出一個不舒服的姿勢，展現出「實施」 (imposition) 的畫面！",
  "impossible": "字根幽默拆解法：im（不） ＋ possible（可能的）\n\n構造聯想：im 字首表否定，源自拉丁文。\n\n記憶畫面：要在五分鐘內跑完五公里是不可能的 (impossible)任務。",
  "impoverished": "幽默諧音法：「硬破威利斯」\n\n發音聯想：impoverished [ɪmˋpɑvərɪʃt] 唸起來就像「硬破威利斯」。\n\n記憶畫面：「硬破威利斯」威利破產後變得非常赤貧 (impoverished)。",
  "impractical": "字根幽默拆解法：im（不） ＋ practical（實際的）\n\n構造聯想：im- 是否定字首，practical 來自 practice（練習、實踐），合起來就是不能實踐的。\n\n記憶畫面：他提議在沙漠裡蓋滑雪場，這想法太不切實際 (impractical)了，根本無法執行。",
  "impress": "字根幽默拆解法：im（深深刻進心底裡面）＋ press（用力蓋下清晰印記）\n\n構造聯想：impress 就是表演得太精彩而在評審腦海裡「深深刻進心底裡面」，像鋼印一樣「用力蓋下清晰印記」。\n\n記憶畫面：面試新同學用吉他自彈自唱自創英文歌，琴聲跟創意直接「深深刻進心底裡面」在學長心中「用力蓋下清晰印記」，真的讓人留下極深印象使欽佩 (impress)！",
  "impression": "幽默諧音法：「伊姆撲瑞閃」\n\n發音聯想：impression [͵ɪmˋprɛʃən] 唸起來就像「伊姆撲瑞閃」。\n\n記憶畫面：腦海浮現「伊姆撲瑞閃」的情境——硬品鞋賞時，新鞋獨特的設計給評審留下了深刻的印象 (impression)。",
  "impressive": "幽默諧音法：「硬撲熱心」\n\n發音聯想：impressive 唸起來有點接近「硬撲熱心」。\n\n記憶畫面：台下觀眾「硬」要「撲」上去獻花表達「熱」「心」，這場演出真是令人印象深刻的 (impressive)！",
  "imprison": "幽默諧音法：「印拍里森」\n\n發音聯想：imprison [͵ɪmˋprɪzən] 唸起來就像「印拍里森」。\n\n記憶畫面：「印拍里森」——把罪犯的相片印在巴黎森林的通緝令上，最後成功將他監禁 (imprison)。",
  "imprisonment": "幽默諧音法：「硬不立著門」\n\n發音聯想：imprisonment [͵ɪmˋprɪzənmənt] 唸起來就像「硬不立著門」。\n\n記憶畫面：犯人被關在牢裡，「硬不立著門（把鐵門深鎖）」進行嚴格的監禁 (imprisonment)與關押。",
  "improper": "幽默諧音法：「硬撲惹」\n\n發音聯想：improper [͵ɪmˋprɑpɚ] 唸起來就像「硬撲惹」。\n\n記憶畫面：在正式場合硬撲向長官，這種行為非常不合適 (improper)且不得體。",
  "improve": "幽默諧音法：「硬鋪路」\n\n發音聯想：improve 聽起來很像「硬鋪路」。\n\n記憶畫面：市府團隊「硬」是在爛路上重新「鋪路」，終於大幅改善 (improve) 了當地的交通狀況！",
  "improvement": "字根幽默拆解法：improve（改善） ＋ ment（名詞）\n\n構造聯想：動詞 improve 加上名詞字尾 ment，表示動作的結果或狀態。\n\n記憶畫面：經過不斷的練習，英文成績終於有了明顯的改善 (improvement)與進步。",
  "improvised": "字根幽默拆解法：im（不） ＋ provide（準備） ＋ ed（過去式）\n\n構造聯想：improvise 就是沒有準備的即興演出，常指臨時湊合。\n\n記憶畫面：從「準備」的概念延伸，演員在舞台上忘詞了，只好即席創作表演 (improvised) 一段對白來救場。",
  "impulse": "字根幽默拆解法：im（往心頭裡面）＋ pulse（咚咚跳動脈搏推一下）\n\n構造聯想：impulse 就是逛夜市看到最後一盒章魚燒時「往心頭裡面」「跳動推一下」立刻掏錢買下的瞬間。\n\n記憶畫面：明明晚餐吃超飽路過甜品店卻被草莓塔勾住視線，心裡「往心頭裡面」突然像心電圖一樣「跳動推一下」馬上端進籃子，這股念頭正是衝動與推動力脈衝 (impulse)！",
  "in": "幽默諧音法：「伊恩」\n\n發音聯想：in [ɪn] 唸起來就像「伊恩」。\n\n記憶畫面：聽到一聲「伊恩」，就看到請把闖關紀念章精準印在集點卡的方格裡面與之內 (in)！",
  "in-depth": "字根幽默拆解法：in（進入） ＋ depth（深度）\n\n構造聯想：depth 是名詞，加上 in 變成形容詞，表示進入深度。\n\n記憶畫面：從「進入」的概念延伸，這場會議我們進行了深入的 (in-depth)討論，把每個細節都挖出來看。",
  "inability": "字根幽默拆解法：in（不） ＋ ability（能力）\n\n構造聯想：將 in（不） ＋ ability（能力） 結合在一起，就能輕鬆推導出「無能」的意思。\n\n記憶畫面：印出來的成績單拿去比，發現自己無能 (inability) 為力，只能被踢出局。",
  "inaccurate": "字根幽默拆解法：in（不） ＋ accurate（精確的）\n\n構造聯想：accurate 源自拉丁文 curare（照顧），引申為精確照顧到細節，加 in 變否定。\n\n記憶畫面：測量數據時少算了一個零，導致結果完全不精確 (inaccurate)。",
  "inactive": "字根幽默拆解法：in（不） ＋ active（活躍的）\n\n構造聯想：active 是動態的，加上否定前綴 in，形容人或機器懶散停滯。\n\n記憶畫面：從「活躍」的概念延伸，這台舊電腦已經閒置多年，處於完全不運轉的 (inactive)狀態。",
  "inadequacy": "字根幽默拆解法：in（不） ＋ adequacy（足夠）\n\n構造聯想：形容能力不足或事物不符合需求，帶有負面評價。\n\n記憶畫面：他在台上表現出的不充分 (inadequacy)，讓他覺得自己完全無法勝任這份工作。",
  "inadequate": "字根幽默拆解法：in（不） ＋ adequate（足夠的）\n\n構造聯想：adequate 意為足夠，inadequate 常用於形容資源、能力或表現不足。\n\n記憶畫面：從「足夠」的概念延伸，準備的食物只有一小盤，對於一百人的派對來說顯然是不充分的 (inadequate)。",
  "inanimate": "字根幽默拆解法：in（完全沒有任何）＋ anim（跳動生命氣息）＋ ate（呈現靜物狀態）\n\n構造聯想：inanimate 就是像鵝卵石與課桌椅一樣「完全沒有任何」「跳動生命氣息」，一直「呈現靜物狀態」待在原地。\n\n記憶畫面：自然博物館玻璃櫃裡的礦石結晶「完全沒有任何」會呼吸的「跳動生命氣息」，安安靜靜「呈現靜物狀態」供人欣賞，屬於標準無生命的 (inanimate) 物體！",
  "inattentive": "字根幽默拆解法：in（不） ＋ attentive（注意的）\n\n構造聯想：將 in（不） ＋ attentive（注意的） 結合在一起，就能輕鬆推導出「疏忽的」的意思。\n\n記憶畫面：一個粗心的人硬要拿著天梯去送給丈夫，結果因為太不注意 (inattentive) 路況，直接摔得鼻青臉腫。",
  "inbound": "字根幽默拆解法：in（進入） ＋ bound（方向）\n\n構造聯想：bound 有前往某處的意思，inbound 就是朝向內部的移動。\n\n記憶畫面：從「進入」的概念延伸，機場看板顯示所有入境的 (inbound)班機都已抵達。",
  "inc.": "幽默諧音法：「硬殼」\n\n發音聯想：Inc. [ɪŋk] 唸起來就像「硬殼」。\n\n記憶畫面：公司 (Inc.)就像一個硬殼，保護著內部的資產與員工。",
  "incapacitate": "字根幽默拆解法：incapacity（正式無能力） ＋ ate（使）\n\n構造聯想：將 incapacity（正式無能力） ＋ ate（使） 結合在一起，就能輕鬆推導出「使無能力」的意思。\n\n記憶畫面：因為印卡機器壞了會怕，導致業務停擺，使人無能力處理，展現出使無能力 (incapacitate) 的畫面！",
  "incapacity": "字根幽默拆解法：in（不） ＋ capacity（容量）\n\n構造聯想：將 in（不） ＋ capacity（容量） 結合在一起，就能輕鬆推導出「<正式>無能力」的意思。\n\n記憶畫面：印出來的證件卡在城市門口，證明他無法律資格 (incapacity) 進入。",
  "incendiary": "幽默諧音法：「印森弟欸瑞」\n\n發音聯想：incendiary [ɪnˋsendieri] 唸起來就像「印森弟欸瑞」。\n\n記憶畫面：順著「印森弟欸瑞」的諧音去想：叛亂分子硬要森爹離開放火點，丟下燃燒彈 (incendiary) 引發熊熊大火。",
  "incense": "幽默諧音法：「硬三思」\n\n發音聯想：incense [͵ɪnˋsɛns] 唸起來就像「硬三思」。\n\n記憶畫面：廟宇裡點燃的香 (incense) 煙霧迷漫，讓旁邊衝動的人不得不『硬三思』再做決定。",
  "incentive": "幽默諧音法：「硬森替服」\n\n發音聯想：incentive [͵ɪnˋsɛntɪv] 唸起來就像「硬森替服」。\n\n記憶畫面：公司祭出「硬森替服（硬要提升福利來服人）」的獎金制度，作為員工努力工作的最佳激勵與動機 (incentive)。",
  "inch": "幽默諧音法：「印尺」\n\n發音聯想：inch [ɪntʃ] 唸起來像印著刻度的「印尺」。\n\n記憶畫面：裁縫師拿出精準的「印尺」丈量布料，每一英寸 (inch) 的長度都量得分毫不差！",
  "incident": "字根幽默拆解法：in（插進日常）＋ cid（突然掉下來）＋ ent（事件插曲）\n\n構造聯想：incident 就是平靜的一天裡突然「插進日常」「掉下來」讓人嚇一跳的小「事件插曲」。\n\n記憶畫面：班會開到一半教室外飛進一隻超肥的彩蝶停在講桌停五秒才飛走，這種突然「插進日常」「掉下來」的小「事件插曲」就叫做事件事變 (incident)！",
  "incidental": "字根幽默拆解法：incident（事件） ＋ al（的）\n\n構造聯想：將 incident（事件） ＋ al（的） 結合在一起，就能輕鬆推導出「易發生的」的意思。\n\n記憶畫面：為了洗乾淨一顆D騰（硬幣），順便產生了許多附帶的 (incidental) 雜費與小開銷。",
  "incinerate": "幽默諧音法：「印心那瑞特」\n\n發音聯想：incinerate [͵ɪnˋsɪnɚ͵et] 唸起來就像「印心那瑞特」。\n\n記憶畫面：「印心那瑞特」燒掉心裡的瑞特，展現出「焚化」 (incinerate) 的畫面！",
  "incinerator": "字根幽默拆解法：incinerate（焚燒） ＋ or（人或物）\n\n構造聯想：字尾 -or 表示執行動作的機器或人，這裡指焚燒的機器。\n\n記憶畫面：從「焚燒」的概念延伸，巨大的焚化爐 (incinerator)冒出濃煙，正在處理城市裡的垃圾。",
  "inclination": "幽默諧音法：「印可內深」\n\n發音聯想：inclination [͵ɪnkləˋneʃən] 唸起來就像「印可內深」。\n\n記憶畫面：你在心裡蓋了一個印章，代表內心深處的傾向 (inclination)，這就是你的意向。",
  "incline": "幽默諧音法：「硬跨來嗯」\n\n發音聯想：incline [͵ɪnˋklaɪn] 唸起來就像「硬跨來嗯」。\n\n記憶畫面：山路非常陡峭，「硬跨來嗯（硬著頭皮跨過斜坡）」去爬山，身體也不禁向前傾斜 (incline)。",
  "include": "幽默諧音法：「硬客錄得」\n\n發音聯想：include [͵ɪnˋklud] 唸起來就像「硬客錄得」。\n\n記憶畫面：「硬客錄得」把所有好朋友的名字通通包含 (include)在這次的聚會名單中。",
  "including": "字根幽默拆解法：in（不） ＋ clud（關閉） ＋ ing（動作或形容詞）\n\n構造聯想：將 in（不） ＋ clud（關閉） ＋ ing（動作或形容詞） 結合在一起，就能輕鬆推導出「包括」的意思。\n\n記憶畫面：音樂地窖裡釘滿了各種樂器，包括 (including) 吉他、貝斯和小提琴。",
  "inclusion": "幽默諧音法：「印可路然」\n\n發音聯想：inclusion [ɪnˋkluʒ(ə)n] 唸起來就像「印可路然」。\n\n記憶畫面：聯想到「印可路然」的畫面：我們把這份名單印出來，放入庫存路選，這就是包含 (inclusion) 的過程。",
  "inclusive": "字根幽默拆解法：in（不） ＋ clus（關閉） ＋ ive（有傾向的）\n\n構造聯想：將 in（不） ＋ clus（關閉） ＋ ive（有傾向的） 結合在一起，就能輕鬆推導出「包含的」的意思。\n\n記憶畫面：度假村的費用硬是把所有魯蛇絲（私）房錢都包含 (inclusive) 進去，也就是包括一切費用在內。",
  "incoherent": "字根幽默拆解法：in（不） ＋ coherent（連貫的）\n\n構造聯想：coherent 來自 co-（一起）+ herere（黏著），意為黏在一起，incoherent 就是黏不起來。\n\n記憶畫面：從「連貫」的概念延伸，醉漢說話顛三倒四，完全是語無倫次的 (incoherent)狀態。",
  "income": "字根幽默拆解法：in（進來） ＋ come（來）\n\n構造聯想：與出費、支出（outcome / expense）相對的高頻經濟詞彙。\n\n記憶畫面：薪水準時匯到戶頭裡，錢財源源不絕地進來，形成穩定的收入 (income)。",
  "incoming": "字根幽默拆解法：in（進入） ＋ coming（來）\n\n構造聯想：由 in 和 come 組成，非常直觀的進來之意。\n\n記憶畫面：手機螢幕顯示有來電，這是即將接聽的進來的 (incoming) 來電。",
  "incompetence": "字根幽默拆解法：in（不） ＋ competence（能力）\n\n構造聯想：competence 是競爭力或能力，incompetence 就是缺乏這些能力。\n\n記憶畫面：從「能力」的概念延伸，由於他的嚴重不勝任 (incompetence)，導致整個專案宣告失敗，大家對他感到失望。",
  "incompetent": "字根幽默拆解法：in（不） ＋ competent（有能力的）\n\n構造聯想：將 in（不） ＋ competent（有能力的） 結合在一起，就能輕鬆推導出「無能力的」的意思。\n\n記憶畫面：那個經理做決策總是賠錢又折騰，大家都說他真是個無能的領導者，展現出無能力的 (incompetent) 的畫面！",
  "incompetently": "字根幽默拆解法：incompetent（無能力的） ＋ ly（地）\n\n構造聯想：將 incompetent（無能力的） ＋ ly（地） 結合在一起，就能輕鬆推導出「不稱職地」的意思。\n\n記憶畫面：硬要看這張爛配置圖，結果做得一塌糊塗，非常不稱職 (incompetently)。",
  "incomplete": "字根幽默拆解法：in（不） ＋ complete（完全的）\n\n構造聯想：將 in（不） ＋ complete（完全的） 結合在一起，就能輕鬆推導出「不完全的」的意思。\n\n記憶畫面：這份報告只寫了一半，資料不完整 (incomplete)，印出來也沒辦法練習。",
  "incomprehensible": "幽默諧音法：「印看撲瑞恨」\n\n發音聯想：incomprehensible [ɪn͵kɑmprɪˋhensəb(ə)l] 唸起來就像「印看撲瑞恨」。\n\n記憶畫面：聽到一聲「印看撲瑞恨」，就看到他的行為無法理解的 (incomprehensible)，讓人無法理解他為什麼要這樣做。",
  "inconsistency": "字根幽默拆解法：in（不） ＋ consistency（一致性）\n\n構造聯想：由 consist（一致）衍生，in- 為否定字首。\n\n記憶畫面：他今天說要減肥，明天又大吃炸雞，這種前後不符的行為簡直是不一致 (inconsistency) 的代表。",
  "inconsistent": "字根幽默拆解法：in（不） ＋ consistent（一致的）\n\n構造聯想：consistent 意為前後一致，inconsistent 常用於形容人品或數據矛盾。\n\n記憶畫面：從「一致」的概念延伸，他今天說要減肥，明天卻大吃大喝，這種行為前後矛盾 (inconsistent)。",
  "inconvenience": "字根幽默拆解法：in（不） ＋ convenience（方便）\n\n構造聯想：convenience 是方便，加上 in- 變成不方便。\n\n記憶畫面：從「方便」的概念延伸，這場大雨造成交通不便 (inconvenience)，大家都要繞路，真的非常麻煩。",
  "inconvenient": "字根幽默拆解法：in（不） ＋ convenient（方便的）\n\n構造聯想：convenient 意為方便，加上 in 變成否定，是日常生活中最常用的抱怨詞。\n\n記憶畫面：半夜三點打電話來，這時間點實在太不方便 (inconvenient)了。",
  "incorporate": "字根幽默拆解法：in（進入） ＋ corpor（身體團體）\n\n構造聯想：in（進入）+ corpor（身體/團體，源自 corpus），意為納入團體中。\n\n記憶畫面：從「進入」的概念延伸，將新的創意合併 (incorporate)到舊的計畫中，讓整個方案更完整。",
  "incorporation": "字根幽默拆解法：incorporate（合併） ＋ tion（名詞）\n\n構造聯想：由動詞 incorporate 變來的名詞，指合併的狀態或公司本身。\n\n記憶畫面：從「合併 (incorporation)」的概念延伸，這份文件記錄了該團體組織的成立過程。",
  "incorrect": "字根幽默拆解法：in（不） ＋ correct（正確的）\n\n構造聯想：字首 in 表示否定，correct 是正確的，組合起來就是錯誤的、不適當的。\n\n記憶畫面：數學考卷上被打了很多紅叉叉，代表答案完全不正確 (incorrect)。",
  "increase": "字根幽默拆解法：in（進入） ＋ crease（摺痕擴展）\n\n構造聯想：當名詞時重音在第一音節（increase），當動詞時重音在第二音節。\n\n記憶畫面：從「進入」的概念延伸，物價不斷往上調漲，生活成本跟著增加 (increase)。",
  "increasing": "字根幽默拆解法：increase（增加） ＋ ing（動作或形容詞）\n\n構造聯想：將 increase（增加） ＋ ing（動作或形容詞） 結合在一起，就能輕鬆推導出「增長」的意思。\n\n記憶畫面：物價不斷增長 (increasing)，聽到這個消息讓人想哭（crea）醒（sing），音（in）量都變大了。",
  "increasingly": "幽默諧音法：「因克麗絲因」\n\n發音聯想：increasingly [ɪnˋkrisɪŋli] 唸起來就像「因克麗絲因」。\n\n記憶畫面：「因克麗絲因個力」越來越有力量，展現出「漸增地」 (increasingly) 的畫面！",
  "incredibility": "字根幽默拆解法：in（不） ＋ credibility（可信度）\n\n構造聯想：cred 意為相信（如 credit 信用），incredibility 就是不可相信的狀態。\n\n記憶畫面：他說的故事太離譜，完全沒有任何可信度可言，展現出「不可信」 (incredibility) 的畫面！",
  "incredible": "幽默諧音法：「硬可累波」\n\n發音聯想：incredible [͵ɪnˋkrɛdəbəl] 唸起來就像「硬可累波」。\n\n記憶畫面：這項任務簡直難到硬可累波（硬是可以累到波濤洶湧），讓人難以置信 (incredible)。",
  "incredulous": "字根幽默拆解法：in（不） ＋ cred（相信） ＋ ulous（形容詞）\n\n構造聯想：字根 cred 代表相信，如 credit 信用。\n\n記憶畫面：從「相信」的概念延伸，聽到誇張的謊言，他臉上露出難以置信的 (incredulous)表情。",
  "incur": "幽默諧音法：「因可」\n\n發音聯想：incur [͵ɪnˋkɝ] 唸起來就像「因可」。\n\n記憶畫面：因為你開車違規，因可 (incur) 招致了一張昂貴的罰單。",
  "indebt": "字根幽默拆解法：in（進入） ＋ debt（債務）\n\n構造聯想：debt 中的 b 不發音，記住這個拼寫可以避免寫錯。\n\n記憶畫面：因為借了朋友一大筆錢，我現在深深地陷入了債務之中，展現出「使負債」 (indebt) 的畫面！",
  "indecisive": "字根幽默拆解法：in（不） ＋ decisive（決定性的）\n\n構造聯想：decisive 來自 decide（決定），加上字首 in- 變成否定。\n\n記憶畫面：從「決定」的概念延伸，面對菜單上五十種飲料，他總是猶豫不決，真是個優柔寡斷的 (indecisive)人。",
  "indeed": "幽默諧音法：「硬低得」\n\n發音聯想：indeed [͵ɪnˋdid] 唸起來就像「硬低得」。\n\n記憶畫面：這題考試真的很難，硬低得 (indeed) 大家都考不及格，這確實是事實。",
  "indefinite": "字根幽默拆解法：in（不） ＋ definite（確定的）\n\n構造聯想：definite 來自 define（定義），加上字首 in- 表示無法定義。\n\n記憶畫面：從「確定」的概念延伸，老闆說這項工程無限期 (indefinite)延後，完全沒有給出一個確切的日期。",
  "indemnify": "字根幽默拆解法：in（使之） ＋ demn（賠償）\n\n構造聯想：字首 in 表示使之，demn 源自 damage（損害），合起來意指「使免受損害」。\n\n記憶畫面：公司保了巨額險，若發生意外保險公司必須賠償 (indemnify) 所有損失。",
  "independence": "字根幽默拆解法：in（不） ＋ dependent（依賴的）\n\n構造聯想：由形容詞 independent 去掉 t 加 ce 轉為名詞，字首 in 表示否定。\n\n記憶畫面：孩子長大了不再依賴父母，展現出獨立 (independence)自主的個性。",
  "independent": "字根幽默拆解法：in（不） ＋ dependent（依賴的）\n\n構造聯想：將 in（不） ＋ dependent（依賴的） 結合在一起，就能輕鬆推導出「獨立的」的意思。\n\n記憶畫面：硬得逼朋友硬是要逼朋友自己做事，從此變得獨立 (independent)。",
  "independently": "字根幽默拆解法：independent（獨立的） ＋ ly（地）\n\n構造聯想：將 independent（獨立的） ＋ ly（地） 結合在一起，就能輕鬆推導出「獨立地」的意思。\n\n記憶畫面：安得莉印資料時不用別人幫忙，自己獨立 (independently) 自主地完成。",
  "indestructible": "字根幽默拆解法：in（不） ＋ destruct（破壞） ＋ ible（能的）\n\n構造聯想：字根 struct 代表建造，加上 de（去掉/反向）就是破壞，前面加 in 表示否定。\n\n記憶畫面：超人穿著斗篷站在爆炸中心，因為他是堅不可摧的 (indestructible)，任何破壞都無法傷他分毫。",
  "index": "幽默諧音法：「硬的克斯」\n\n發音聯想：index [ˋɪndɛks] 唸起來就像「硬的克斯」。\n\n記憶畫面：為了查資料，大家只好去翻那本『硬的克斯』精裝書後面的厚重索引 (index)。",
  "india": "幽默諧音法：「印地亞」\n\n發音聯想：india [ˋɪndiə] 唸起來就像「印地亞」。\n\n記憶畫面：地圖上標示著印度 (india)，它是南亞的一個大國。",
  "indicate": "幽默諧音法：「印達客特」\n\n發音聯想：indicate [ˋɪndə͵ket] 唸起來就像「印達客特」。\n\n記憶畫面：腦海浮現「印達客特」的情境——印地安刻得在石壁上的記號，用來清楚指出 (indicate) 水源的方向。",
  "indication": "字根幽默拆解法：indicate（指出） ＋ tion（動作或狀態）\n\n構造聯想：將 indicate（指出） ＋ tion（動作或狀態） 結合在一起，就能輕鬆推導出「跡象」的意思。\n\n記憶畫面：硬點決定買這台車，因為儀表板上的指針是最好的性能跡象 (indication)。",
  "indicator": "字根幽默拆解法：in（進入） ＋ dic（說） ＋ ator（人或物）\n\n構造聯想：字根 dic- 有「說」的意思，indicator 就是「說出真相的東西」。\n\n記憶畫面：經濟成長率是衡量國家發展的重要指標 (indicator)。",
  "indifference": "幽默諧音法：「硬低分冷思」\n\n發音聯想：indifference [͵ɪnˋdɪfɚəns] 唸起來就像「硬低分冷思」。\n\n記憶畫面：學生考了『硬低分』卻一臉漠不關心 (indifference)，完全不在乎成績。",
  "indifferent": "幽默諧音法：「硬地分潤」\n\n發音聯想：indifferent [͵ɪnˋdɪfrənt] 唸起來就像「硬地分潤」。\n\n記憶畫面：老闆對公司的虧損採取不感興趣 (indifferent)且冷淡的態度，硬要照原本規定分潤。",
  "indignant": "幽默諧音法：「硬踢個妳的」\n\n發音聯想：indignant [͵ɪnˋdɪɡnənt] 唸起來就像「硬踢個妳的」。\n\n記憶畫面：女生遭到不平等的對待，憤憤不平 (indignant)地氣到想硬踢對方一腳。",
  "indignation": "幽默諧音法：「印弟格內閃」\n\n發音聯想：indignation [͵ɪndɪɡˋneʃən] 唸起來就像「印弟格內閃」。\n\n記憶畫面：聯想到「印弟格內閃」的畫面：黑心建商偷工減料，硬地挖個內休（內心充滿休想得逞的憤怒 (indignation) ），激起居民強烈的義憤與憤慨。",
  "indispensable": "幽默諧音法：「硬底子拚斯」\n\n發音聯想：indispensable [͵ɪndɪˋspɛnsəbəl] 唸起來就像「硬底子拚斯」。\n\n記憶畫面：這項核心技術是團隊不可或缺的 (indispensable)寶貝，大家都要硬底子拚固守護。",
  "indisposed": "字根幽默拆解法：in（不、沒有）＋ disposed（處在舒服準備好狀態）\n\n構造聯想：indisposed 就是早上起來鼻塞頭暈，「沒有」「處在舒服準備好狀態」所以也不太想出門。\n\n記憶畫面：原本約好週末去爬山結果前晚稍微著涼打噴嚏，「沒有」「處在舒服準備好狀態」只好禮貌傳訊息請假在家蓋被子，形容身體不適或不情願的 (indisposed)！",
  "individual": "幽默諧音法：「印達維哲哇」\n\n發音聯想：individual [͵ɪndəˋvɪdʒəwəl] 唸起來就像「印達維哲哇」。\n\n記憶畫面：腦海浮現「印達維哲哇」的情境——音地的微珠每一個微小的珍珠都代表獨一無二的個人 (individual)！",
  "individualism": "字根幽默拆解法：individual（個人） ＋ ism（主義）\n\n構造聯想：字根 divid 是分開，in- 是不，合起來就是不可分割的個體。\n\n記憶畫面：畫面上一個人獨自站在舞台中央，堅持自己的風格，這就是個人主義 (individualism)。",
  "individuality": "字根幽默拆解法：individual（個人） ＋ ity（性質）\n\n構造聯想：由 individual 衍生，強調與眾不同的特質。\n\n記憶畫面：每個人都有獨特的穿衣風格，這就是展現個人特徵 (individuality)的方式。",
  "indoor": "字根幽默拆解法：in（不） ＋ door（門）\n\n構造聯想：將 in（不） ＋ door（門） 結合在一起，就能輕鬆推導出「室內的」的意思。\n\n記憶畫面：門裡面就是室內的 (indoor) 活動。",
  "indoors": "幽默諧音法：「硬倒絲」\n\n發音聯想：indoors [ˋɪn͵dɔrz] 唸起來就像「硬倒絲」。\n\n記憶畫面：外面風雨太大，蜘蛛網硬倒絲在玻璃窗上，大家只好待在室內 (indoors)。",
  "induce": "字根幽默拆解法：in（引進去）＋ duce（牽著走）\n\n構造聯想：induce 就是像拿著雞排香味把路人一步步「牽著走」「引進去」店裡。\n\n記憶畫面：麵包店剛出爐把電風扇往門口吹，那股奶油香成功把過路客人全都「引進去」「牽著走」乖乖排隊買單，超會誘導 (induce) 消費！",
  "indulge": "幽默諧音法：「伊納達」\n\n發音聯想：indulge [͵ɪnˋdʌldʒ] 唸起來就像「伊納達」。\n\n記憶畫面：聯想到「伊納達」的畫面：減肥失敗後，她決定沈迷於 (indulge) 於巧克力蛋糕中。",
  "industrial": "字根幽默拆解法：industry（工業） ＋ ial（工業）\n\n構造聯想：名詞 industry（工業）字尾 y 去掉加上 ial 變成工業的形容詞。\n\n記憶畫面：台灣在經濟起飛時期建立了許多工業的 (industrial) 園區。",
  "industrialize": "字根幽默拆解法：industry（工業工廠）＋ al ＋ ize（化為）\n\n構造聯想：industrialize 就是把一片空地全部「化為」滿滿的「工業工廠」。\n\n記憶畫面：為了讓小鎮經濟起飛，市長把原本荒涼的空地通通「化為」整排現代化「工業工廠」，徹底讓整座城市工業化 (industrialize)！",
  "industry": "幽默諧音法：「印達斯特瑞」\n\n發音聯想：industry [ˋɪndəstri] 唸起來就像「印達斯特瑞」。\n\n記憶畫面：順著「印達斯特瑞」的諧音去想：科技園區裡一排排廠房白天黑夜都像引大廠力一樣勤勞生產晶片與電動車，這個字除了工業產業行業外也指像蜜蜂般的勤奮 (industry)！",
  "ineffective": "字根幽默拆解法：in（不） ＋ effective（有效的）\n\n構造聯想：effective 是有效的，加上否定字首 in 變成無效。\n\n記憶畫面：這個新政策完全無效果的 (ineffective)，根本解決不了交通問題。",
  "inefficiency": "字根幽默拆解法：in（不） ＋ efficiency（效率）\n\n構造聯想：efficiency 是效率，加上 in 變成否定，指浪費資源或時間的狀態。\n\n記憶畫面：這家公司的行政流程充滿了無效率 (inefficiency)的環節，導致工作進度嚴重落後。",
  "inefficiently": "字根幽默拆解法：in（不） ＋ efficiently（高效率地）\n\n構造聯想：將 in（不） ＋ efficiently（高效率地） 結合在一起，就能輕鬆推導出「無效率地」的意思。\n\n記憶畫面：硬要用這種浪費時間的方法做事，導致過程毫無效率 (inefficiently)。",
  "ineptly": "幽默諧音法：「伊內撲特利」\n\n發音聯想：ineptly [ɪˋneptli] 唸起來就像「伊內撲特利」。\n\n記憶畫面：腦海浮現「伊內撲特利」的情境——跑得不夠快還硬要跑，結果姿勢非常笨拙、不適當地 (ineptly) 跌倒。",
  "inessential": "字根幽默拆解法：in（不） ＋ essential（必要的、核心的）\n\n構造聯想：「不是」真正「必要的」東西，就是無關緊要的 (inessential) 雜物。\n\n記憶畫面：出發前才發現行李箱塞滿了「不」「必要的」裝飾品與小零食，把這些無關緊要的 (inessential) 東西拿出來才拉得上拉鍊！",
  "inevitable": "幽默諧音法：「伊內瓦塔巴」\n\n發音聯想：inevitable [͵ɪnˋɛvətəbəl] 唸起來就像「伊內瓦塔巴」。\n\n記憶畫面：聽到一聲「伊內瓦塔巴」，就看到這張舊椅子硬是廢了被踢得包起來，這是歲月流逝必然發生的 (inevitable) 結果。",
  "inevitably": "字根幽默拆解法：inevitable（不可避免的） ＋ y（多的）\n\n構造聯想：將 inevitable（不可避免的） ＋ y（多的） 結合在一起，就能輕鬆推導出「無法避免地」的意思。\n\n記憶畫面：如果不注意健康，生病是無法避免 (inevitably) 的，硬要為他補力也沒用。",
  "inexact": "字根幽默拆解法：in（不） ＋ exact（精確的）\n\n構造聯想：exact 是精確，加上否定字首 in 就變成不精確。\n\n記憶畫面：測量師的數據不精確，被老闆罵說這份報告完全是不精確的 (inexact) 的。",
  "inexpertly": "幽默諧音法：「印愛克斯波」\n\n發音聯想：inexpertly [ɪnˋɛkspɝtli] 唸起來就像「印愛克斯波」。\n\n記憶畫面：「印愛克斯波特力」——出口產品時包裝得像外行 (inexpertly)一樣不熟練，漏洞百出。",
  "inexplicable": "幽默諧音法：「伊泥可斯撲」\n\n發音聯想：inexplicable [͵ɪnɪkˋsplɪkəb(ə)l] 唸起來就像「伊泥可斯撲」。\n\n記憶畫面：聯想到「伊泥可斯撲」的畫面：這場突如其來的暴雨簡直費解的 (inexplicable)，完全無法用氣象學解釋。",
  "infamous": "幽默諧音法：「硬飛某事」\n\n發音聯想：infamous [ˋɪnfəməs] 唸起來就像「硬飛某事」。\n\n記憶畫面：那個小偷因為偷竊行為而聲名狼藉 (infamous)，大家都在談論他硬飛某事（硬要飛去某地幹壞事）。",
  "infancy": "字根幽默拆解法：in（不） ＋ fancy（喜歡）\n\n構造聯想：將 in（不） ＋ fancy（喜歡） 結合在一起，就能輕鬆推導出「嬰兒期」的意思。\n\n記憶畫面：這個新創產業還處於嬰兒期 (infancy)，發展空間非常大。",
  "infant": "幽默諧音法：「印放特」\n\n發音聯想：infant [ˋɪnfənt] 唸起來就像「印放特」。\n\n記憶畫面：聯想到「印放特」的畫面：因煩而哭的小寶寶，原來是肚子餓了在找媽媽餵奶，展現出嬰兒 (infant) 的畫面！",
  "infect": "幽默諧音法：「因肥客」\n\n發音聯想：infect [͵ɪnˋfɛkt] 唸起來就像「因肥客」。\n\n記憶畫面：「因肥客」身上帶有病毒，去吃到飽餐廳用餐不小心傳染 (infect)給整桌人。",
  "infection": "字根幽默拆解法：infect（傳染） ＋ tion（動作或狀態）\n\n構造聯想：將 infect（傳染） ＋ tion（動作或狀態） 結合在一起，就能輕鬆推導出「傳染」的意思。\n\n記憶畫面：硬回糞區清理結果不慎造成細菌感染 (infection)，傷口紅腫發炎。",
  "infectious": "字根幽默拆解法：infect（傳染） ＋ ious（充滿的）\n\n構造聯想：將 infect（傳染） ＋ ious（充滿的） 結合在一起，就能輕鬆推導出「傳染的」的意思。\n\n記憶畫面：流感病毒硬發克（發作）在秀絲（小姐）身上，具有極強的傳染 (infectious) 性。",
  "infer": "幽默諧音法：「音符」\n\n發音聯想：infer [͵ɪnˋfɝ] 唸起來就像「音符」。\n\n記憶畫面：從跳動的音符中，我能推斷 (infer)出這首曲子想表達的悲傷情緒。",
  "inference": "幽默諧音法：「硬分蕊斯」\n\n發音聯想：inference [ˋɪnfɚəns] 唸起來就像「硬分蕊斯」。\n\n記憶畫面：警官靠著現場殘留的「硬分蕊斯（硬要分析斯因線索）」，做出精準的邏輯推理與推論 (inference)結果。",
  "inferior": "幽默諧音法：「因菲力噢」\n\n發音聯想：inferior [͵ɪnˋfɪriɚ] 唸起來就像「因菲力噢」。\n\n記憶畫面：「因菲力噢」這塊牛排比較次等 (inferior)，所以吃起來沒有菲力那麼好！",
  "infertile": "字根幽默拆解法：in（不） ＋ fertile（肥沃）\n\n構造聯想：字首 in 表示否定，fertile 表示肥沃的。\n\n記憶畫面：這塊土地完全不肥沃，種什麼都長不出來，顯得非常不育的 (infertile)。",
  "infestation": "字根幽默拆解法：in（鑽進家裡來）＋ fest（整群擠來開派對）＋ ation（麻煩狀態）\n\n構造聯想：infestation 就是小螞蟻發現桌上甜食後「鑽進家裡來」呼朋引伴「整群擠來開派對」的「麻煩狀態」。\n\n記憶畫面：吃餅乾掉了一塊餅乾屑沒掃乾淨，兩小時後整條桌子爬滿貪吃小螞蟻像「鑽進家裡來」「整群擠來開派對」，這種大批滋生侵擾 (infestation) 趕快拿抹布清掉！",
  "infested": "幽默諧音法：「硬飛踢」\n\n發音聯想：infested [ɪnˋfestɪd] 唸起來就像「硬飛踢」。\n\n記憶畫面：房間裡蟑螂大批滋生 (infested)，硬是飛過來踢到我的臉。",
  "infinite": "幽默諧音法：「因芬妮特」\n\n發音聯想：infinite [ˋɪnfənət] 唸起來就像「因芬妮特」。\n\n記憶畫面：因為芬妮特擁有無限的 (infinite)創意，所以她的設計作品靈感總是無窮無盡。",
  "infinitum": "幽默諧音法：「印菲奶坦」\n\n發音聯想：infinitum [ɪnfɪˋnaɪtəm] 唸起來就像「印菲奶坦」。\n\n記憶畫面：聽到一聲「印菲奶坦」，就看到這條路彷彿印非尼騰（無限地 (infinitum) ）延伸，怎麼走都走不到盡頭。",
  "infinity": "幽默諧音法：「因飛你提」\n\n發音聯想：infinity [͵ɪnˋfɪnɪti] 唸起來就像「因飛你提」。\n\n記憶畫面：宇宙的廣大是無限 (infinity)的，因飛你提（因為飛得高，你提起）也摸不到邊際。",
  "inflammable": "字根幽默拆解法：in（進入） ＋ flammable（易燃）\n\n構造聯想：in- 在此並非否定，而是加強語氣，意為進入燃燒狀態。\n\n記憶畫面：這堆木頭硬是發爛了，變得非常容易燃 (inflammable)燒。",
  "inflammatory": "幽默諧音法：「印福賴媽偷」\n\n發音聯想：inflammatory [ɪnˋflæmə͵tɔri] 唸起來就像「印福賴媽偷」。\n\n記憶畫面：聽到一聲「印福賴媽偷」，就看到關節發炎 (inflammatory) 腫痛得硬要飛踢，醫生說要用消炎藥理來滅痛。",
  "inflation": "幽默諧音法：「印福累閃」\n\n發音聯想：inflation [͵ɪnˋfleʃən] 唸起來就像「印福累閃」。\n\n記憶畫面：聯想到「印福累閃」的畫面：硬飛溜訓直直往上飆，這就是可怕的通貨膨脹 (inflation)。",
  "inflict": "幽默諧音法：「硬飛克」\n\n發音聯想：inflict [͵ɪnˋflɪkt] 唸起來就像「硬飛克」。\n\n記憶畫面：戰爭給百姓帶來了巨大的痛苦，硬飛克（硬要飛過來克制）這些無辜的人，展現出「給予」 (inflict) 的畫面！",
  "influence": "幽默諧音法：「硬流汗」\n\n發音聯想：influence [ˋɪnfluəns] 唸起來就像「硬流汗」。\n\n記憶畫面：網紅的一言一行具有強大的影響 (influence)力，讓粉絲跟著努力健身、硬流汗。",
  "influencer": "字根幽默拆解法：influence（影響） ＋ er（的人或物）\n\n構造聯想：將 influence（影響） ＋ er（的人或物） 結合在一起，就能輕鬆推導出「網紅」的意思。\n\n記憶畫面：知名網紅 (influencer) 開直播帶貨，強大的帶貨能力讓廠商福氣財源滾滾來。",
  "influential": "幽默諧音法：「印福路恩莎」\n\n發音聯想：influential [͵ɪnfluˋɛnʃəl] 唸起來就像「印福路恩莎」。\n\n記憶畫面：聽到一聲「印福路恩莎」，就看到硬佛流安秀爾網紅硬要在佛流（flow）安插產品秀爾（show），非常有影響 (influential) 力。",
  "influx": "幽默諧音法：「硬發拉克斯」\n\n發音聯想：influx [ˋɪn͵flʌks] 唸起來就像「硬發拉克斯」。\n\n記憶畫面：旅遊旺季時，大量遊客湧進 (influx)這個小鎮，硬發拉克斯（硬要發動拉車進來）。",
  "info": "幽默諧音法：「硬否」\n\n發音聯想：info [ˋɪnfo] 唸起來就像「硬否」。\n\n記憶畫面：這份資訊 (info)太重要了，你硬否（硬要否認）也沒用，證據都在這。",
  "inform": "幽默諧音法：「應轟」\n\n發音聯想：inform [͵ɪnˋfɔrm] 唸起來就像「應轟」。\n\n記憶畫面：里長用大聲公應轟（廣播通知 (inform)）村民注意颱風來襲。",
  "informal": "字根幽默拆解法：in（不） ＋ formal（正式的）\n\n構造聯想：formal 加上否定字首 in-，變成非正式。\n\n記憶畫面：這是一場不正式的 (informal)聚會，大家穿拖鞋來就行了。",
  "information": "字根幽默拆解法：in（不） ＋ formation（形成）\n\n構造聯想：將 in（不） ＋ formation（形成） 結合在一起，就能輕鬆推導出「資訊」的意思。\n\n記憶畫面：硬付佛的魔法書裡記載了全世界最機密的大量資訊 (information) 與情報。",
  "informative": "幽默諧音法：「硬佛賣替夫」\n\n發音聯想：informative [͵ɪnˋfɔrmətɪv] 唸起來就像「硬佛賣替夫」。\n\n記憶畫面：「硬佛賣替夫」傳遞資訊，這個佛教神像很教育性的 (informative) （有教育性的、提供有用資訊的）。",
  "infract": "字根幽默拆解法：in（進入） ＋ fract（斷裂） ＋ fraction（違反）\n\n構造聯想：in- 進入，fract 斷裂（與 fraction 同源），把規定弄斷就是違法。\n\n記憶畫面：從「進入」的概念延伸，簽約國私下偷偷毀約，完全不把當初談好的國際協定放在眼裡，展現出「違反」 (infract) 的畫面！",
  "infrastructure": "字根幽默拆解法：infra（下面） ＋ structure（結構）\n\n構造聯想：infra- 是常見字首，表示在下方，structure 是結構。\n\n記憶畫面：從「下面」的概念延伸，政府投入大量資金建設基礎設施 (infrastructure)，像是道路、橋樑和電力系統。",
  "infringe": "幽默諧音法：「印福林吉」\n\n發音聯想：infringe [ɪnˋfrɪndʒ] 唸起來就像「印福林吉」。\n\n記憶畫面：順著「印福林吉」的諧音去想：抄襲者盜用別人的商標和專利，已經嚴重侵害 (infringe) 了原作者的權益。",
  "infringement": "幽默諧音法：「印分取悶斯」\n\n發音聯想：infringement [ɪnˋfrɪndʒmənt] 唸起來就像「印分取悶斯」。\n\n記憶畫面：盜版商印分取悶斯原創作者，被控告侵權 (infringement)並面臨天價罰款。",
  "ingenious": "字根幽默拆解法：in（不） ＋ gen（產生） ＋ ious（充滿的）\n\n構造聯想：將 in（不） ＋ gen（產生） ＋ ious（充滿的） 結合在一起，就能輕鬆推導出「心靈手巧的」的意思。\n\n記憶畫面：工匠用巧思在黃金上印出精美戒指，展現出心靈手巧 (ingenious) 與足智多謀。",
  "ingenuity": "幽默諧音法：「印哲努阿替」\n\n發音聯想：ingenuity [͵ɪndʒəˋnuə͵ti] 唸起來就像「印哲努阿替」。\n\n記憶畫面：聯想到「印哲努阿替」的畫面：師傅運用印金魚養牠的聰明才智，設計出自動餵食與過濾系統，充滿了獨創性 (ingenuity) 與足智多謀。",
  "ingredient": "幽默諧音法：「印格瑞弟安」\n\n發音聯想：ingredient [ɪnˋɡridiənt] 唸起來就像「印格瑞弟安」。\n\n記憶畫面：腦海浮現「印格瑞弟安」的情境——硬格力硬吞秘訣就在於獨特的配方原料與成分 (ingredient)。",
  "inhabit": "字根幽默拆解法：in（不） ＋ habit（習慣）\n\n構造聯想：將 in（不） ＋ habit（習慣） 結合在一起，就能輕鬆推導出「居住於」的意思。\n\n記憶畫面：野生動物硬去這個荒島避難，結果發現這裡早已被人類居住，展現出居住於 (inhabit) 的畫面！",
  "inhabitant": "字根幽默拆解法：inhabit（居住於） ＋ ant（螞蟻）\n\n構造聯想：將 inhabit（居住於） ＋ ant（螞蟻） 結合在一起，就能輕鬆推導出「居民」的意思。\n\n記憶畫面：原住民硬黑爸探頭從部落窗戶往外看，作為這片森林與土地的長久居民 (inhabitant) 與棲息動物。",
  "inhalation": "字根幽默拆解法：in（進入） ＋ hale（呼吸） ＋ ation（名詞結尾）\n\n構造聯想：字根 hale 源自古英語，意為健康或呼吸。\n\n記憶畫面：醫生指示病人進行深度的，把藥物噴霧吸入 (inhalation)肺部。",
  "inherent": "幽默諧音法：「硬核人」\n\n發音聯想：inherent [ɪnˋhɪrənt] 唸起來就像「硬核人」。\n\n記憶畫面：身為硬核人，骨子裡就帶有一種與生俱來的強悍與固有的 (inherent)堅持。",
  "inherit": "幽默諧音法：「伊納哈」\n\n發音聯想：inherit [͵ɪnˋhɛrət] 唸起來就像「伊納哈」。\n\n記憶畫面：聽到一聲「伊納哈」，就看到年輕人順利繼承 (inherit) 爺爺留下的億萬莊園。",
  "initial": "字根幽默拆解法：initiate（開始實施） ＋ al（的）\n\n構造聯想：將 initiate（開始實施） ＋ al（的） 結合在一起，就能輕鬆推導出「開始的」的意思。\n\n記憶畫面：從「開始」的概念延伸，硬去洗歐洲代購的精品皮夾，上面燙印著他名字的開頭首字母 (initial)。",
  "initially": "字根幽默拆解法：initial（開始的） ＋ ly（地）\n\n構造聯想：將 initial（開始的） ＋ ly（地） 結合在一起，就能輕鬆推導出「開始」的意思。\n\n記憶畫面：一尼（你）切裡（切開）蘋果，最初 (initially) 的樣子就是白白的果肉。",
  "initiate": "幽默諧音法：「伊泥希欸特」\n\n發音聯想：initiate [͵ɪnˋɪʃi͵et] 唸起來就像「伊泥希欸特」。\n\n記憶畫面：聽到一聲「伊泥希欸特」，就看到新會所開幕時發給每人『一粒喜氣』的糖果，正式開始實施 (initiate) 新計畫。",
  "initiation": "字根幽默拆解法：init（開始） ＋ iation（名詞）\n\n構造聯想：initiate 是動詞，指發起或開始。\n\n記憶畫面：加入秘密社團的入會儀式，就是一場正式的開始 (initiation)。",
  "initiative": "字根幽默拆解法：initiate（開始實施） ＋ ive（有傾向的）\n\n構造聯想：將 initiate（開始實施） ＋ ive（有傾向的） 結合在一起，就能輕鬆推導出「主動權」的意思。\n\n記憶畫面：姑姑硬姨許阿踢服（硬要阿姨去踢球服輸）展現出積極的主動權 (initiative) 與強烈的主動性。",
  "inject": "幽默諧音法：「硬借客」\n\n發音聯想：inject [͵ɪnˋdʒɛkt] 唸起來就像「硬借客」。\n\n記憶畫面：護士硬借客人的手臂來練習，準備幫病人注射 (inject)疫苗。",
  "injection": "字根幽默拆解法：in（往內）＋ ject（噴射、投擲）＋ ion（名詞）\n\n構造聯想：injection 就是把藥水或資金「往內」「噴射」推進去。\n\n記憶畫面：護理師溫柔地把營養液「往內」「噴射」進點滴管，完成這次無痛注射 (injection)！",
  "injure": "幽默諧音法：「印哲」\n\n發音聯想：injure [ˋɪndʒɚ] 唸起來就像「印哲」。\n\n記憶畫面：腦海浮現「印哲」的情境——他在球場上動作太粗魯，硬抓對手的肩膀導致對方受傷，展現出傷害 (injure) 的畫面！",
  "injured": "幽默諧音法：「硬舉的」\n\n發音聯想：injured [ˋɪndʒɚd] 唸起來就像「硬舉的」。\n\n記憶畫面：健身房裡硬舉的動作太猛，結果腰部受傷 (injured)了。",
  "injury": "字根幽默拆解法：in（不） ＋ jury（陪審團）\n\n構造聯想：將 in（不） ＋ jury（陪審團） 結合在一起，就能輕鬆推導出「傷害」的意思。\n\n記憶畫面：印急救力受傷了就要立刻印出急救指南來出力幫忙，展現出傷害 (injury) 的畫面！",
  "injustice": "字根幽默拆解法：in（不、違反）＋ justice（公平正義）\n\n構造聯想：injustice 就是明明規則寫得清清楚楚卻「不」講道理直接「違反」「公平正義」。\n\n記憶畫面：組隊打掃教室時一個人偷跑去喝飲料，最後竟然頒給摸魚的人最佳勤勞獎，大家大喊太「不」「公平正義」啦，這件事實在太不公正無道義 (injustice)！",
  "ink": "幽默諧音法：「印客」\n\n發音聯想：ink [ɪŋk] 唸起來就像「印客」。\n\n記憶畫面：印客 (ink) 把黑色的墨水塗在活版印刷機上準備出書。",
  "inland": "幽默諧音法：「硬藍的」\n\n發音聯想：inland [ˋɪn͵lænd] 唸起來就像「硬藍的」。\n\n記憶畫面：地圖上那塊『硬藍的』湖泊旁邊，就是遼闊的內地與內陸 (inland)。",
  "inn": "幽默諧音法：「伊恩」\n\n發音聯想：inn [ɪn] 唸起來就像「伊恩」。\n\n記憶畫面：腦海浮現「伊恩」的情境——長途跋涉的旅客腳都硬了，趕快找家小旅館 (inn) 休息！",
  "inner": "幽默諧音法：「硬拿」\n\n發音聯想：inner [ˋɪnɚ] 唸起來就像「硬拿」。\n\n記憶畫面：把東西硬拿進最裡面，代表這是內部的 (inner)核心區域。",
  "innocence": "幽默諧音法：「伊拿散絲」\n\n發音聯想：innocence [ˋɪnəsəns] 唸起來就像「伊拿散絲」。\n\n記憶畫面：順著「伊拿散絲」的諧音去想：硬拿四個聖物證明這位被告內心的天真無邪 (innocence) 與絕對清白。",
  "innocent": "幽默諧音法：「伊拿散特」\n\n發音聯想：innocent [ˋɪnəsənt] 唸起來就像「伊拿散特」。\n\n記憶畫面：順著「伊拿散特」的諧音去想：硬要說森森林的森沒做壞事，展現出無罪的 (innocent) 的畫面！",
  "innovate": "字根幽默拆解法：in（不） ＋ nov（新） ＋ ate（使）\n\n構造聯想：將 in（不） ＋ nov（新） ＋ ate（使） 結合在一起，就能輕鬆推導出「創立」的意思。\n\n記憶畫面：為了在市場存活，公司硬要去位居第一的對手那裡學習如何創立 (innovate)。",
  "innovation": "字根幽默拆解法：in（不） ＋ nov（新） ＋ ation（動作或過程）\n\n構造聯想：將 in（不） ＋ nov（新） ＋ ation（動作或過程） 結合在一起，就能輕鬆推導出「革新」的意思。\n\n記憶畫面：硬拿餵鞋森－科技公司硬是拿出一雙會自動鞋帶的鞋子給學生，這就是一項產品創新 (innovation)。",
  "innovative": "字根幽默拆解法：innovate（創立） ＋ ive（有傾向的）\n\n構造聯想：將 innovate（創立） ＋ ive（有傾向的） 結合在一起，就能輕鬆推導出「創新的」的意思。\n\n記憶畫面：工程師硬是挪開肥胖的防護網，推出了一款極具創新的 (innovative) 科技產品。",
  "innovator": "字根幽默拆解法：in（注入裡頭）＋ nov（全新點子）＋ ator（創造人物）\n\n構造聯想：innovator 就是腦袋天天轉不停，專門幫老商品「注入」「全新點子」的「創造人物」。\n\n記憶畫面：以前飲料杯蓋只能插吸管，有位天才把「全新點子」「注入」設計成可開合小口直接喝，大家紛紛佩服這位改變生活習慣的革新者創新者 (innovator)！",
  "innumerable": "字根幽默拆解法：in（不） ＋ numer（數字） ＋ able（能夠的）\n\n構造聯想：將 in（不） ＋ numer（數字） ＋ able（能夠的） 結合在一起，就能輕鬆推導出「無數的」的意思。\n\n記憶畫面：夜市裡有攤位擺出無數 (innumerable) 個小獎品，老闆大喊硬要摸拉吧，吸引大家來抽獎。",
  "inoffensive": "字根幽默拆解法：in（不） ＋ offensive（冒犯的）\n\n構造聯想：offensive 是冒犯的，加 in- 變相反。\n\n記憶畫面：他講話總是小心翼翼，非常不觸犯人的 (inoffensive)，從不讓任何人感到不舒服。",
  "input": "幽默諧音法：「硬撲它」\n\n發音聯想：input [ˋɪn͵pʊt] 唸起來就像「硬撲它」。\n\n記憶畫面：「硬撲它」把資料快速輸入 (input)到電腦系統裡。",
  "inquire": "幽默諧音法：「伊納快」\n\n發音聯想：inquire [͵ɪnˋkwaɪr] 唸起來就像「伊納快」。\n\n記憶畫面：腦海浮現「伊納快」的情境——警察向目擊證人訊問 (inquire) 當時發生的車禍細節。",
  "inquiring": "字根幽默拆解法：in（進入） ＋ quiring（詢問）\n\n構造聯想：與 inquire 同源，inquire 是動詞，inquiring 是形容詞。\n\n記憶畫面：記者為了寫報導，不斷進入別人的生活圈詢問，展現出愛打聽的 (inquiring)特質。",
  "inquiry": "字根幽默拆解法：in（不） ＋ quir（尋求） ＋ y（多的）\n\n構造聯想：將 in（不） ＋ quir（尋求） ＋ y（多的） 結合在一起，就能輕鬆推導出「詢問」的意思。\n\n記憶畫面：硬虧台莉－記者硬要去櫃檯虧主管莉莉，追問八卦消息進行一場私下詢問 (inquiry)。",
  "inquisitive": "幽默諧音法：「硬虧斯提夫」\n\n發音聯想：inquisitive [ɪnˋkwɪzətɪv] 唸起來就像「硬虧斯提夫」。\n\n記憶畫面：一個叫提夫的人因為太好奇 (inquisitive)，一直問問題，結果被問到硬是虧錢虧到斯，真是愛探究的代價。",
  "insane": "幽默諧音法：「硬塞嗯」\n\n發音聯想：insane [͵ɪnˋsen] 唸起來就像「硬塞嗯」。\n\n記憶畫面：老闆把不可能完成的工作硬塞嗯 (insane)，簡直是瘋了、精神錯亂才會這樣要求。",
  "insanity": "幽默諧音法：「硬塞內提」\n\n發音聯想：insanity [͵ɪnˋsænəti] 唸起來就像「硬塞內提」。\n\n記憶畫面：把大象硬塞內提（內體）裡，這簡直是瘋狂 (insanity)的行為。",
  "insect": "字根幽默拆解法：in（不） ＋ sect（切割）\n\n構造聯想：字首 in 加上 sect（切開），昆蟲身體像被節節切開般。\n\n記憶畫面：昆蟲 (insect) 飛進房間，停在五顏六色的花朵上。",
  "insecure": "字根幽默拆解法：in（不） ＋ secure（安全）\n\n構造聯想：secure 字根源自 se（分開）+ cura（關心/照顧），意指無憂無慮。\n\n記憶畫面：這座橋看起來搖搖欲墜，讓人感到非常不安全 (insecure)。",
  "insecurity": "字根幽默拆解法：insecure（不安全的） ＋ ity（名詞）\n\n構造聯想：加上 ity 後變成名詞，描述一種狀態。\n\n記憶畫面：從「不安」的概念延伸，這份工作的不確定性，讓他充滿了對未來的無把握 (insecurity)感。",
  "insert": "幽默諧音法：「印色特」\n\n發音聯想：insert [͵ɪnˋsɝt] 唸起來就像「印色特」。\n\n記憶畫面：腦海浮現「印色特」的情境——硬塞特進相機背面的插槽裡才能拍照，展現出插入 (insert) 的畫面！",
  "inside": "字根幽默拆解法：in（在…內）＋ side（邊、側）\n\n構造聯想：inside 字面上就是在界線的「內」「側」，代表內部、在裡面。\n\n記憶畫面：外面下大雨，大家全躲進房子「內」「側」的裡面與內部 (inside) 喝熱茶！",
  "insider": "字根幽默拆解法：in（內部） ＋ side（邊面） ＋ er（人）\n\n構造聯想：與 outsider（外人）相對。\n\n記憶畫面：只有內部的人 (insider)才知道這家公司的秘密交易。",
  "insight": "幽默諧音法：「印塞特」\n\n發音聯想：insight [ˋɪn͵saɪt] 唸起來就像「印塞特」。\n\n記憶畫面：「印塞特」－把深刻的見解直接印刷塞進特製的書本裡供人閱讀，展現出「洞察力」 (insight) 的畫面！",
  "insignificant": "字根幽默拆解法：in（不） ＋ significant（重要的、重大的）\n\n構造聯想：「不」「重要」的小事，就是微不足道 (insignificant) 到可以忽略不計。\n\n記憶畫面：對百億企業而言這幾百元的文具零頭根本「不」「重要」，簡直微不足道 (insignificant) 到會計都不想多看一眼！",
  "insist": "字根幽默拆解法：in（插進去釘牢）＋ sist（站在原地不退讓）\n\n構造聯想：insist 就是雙腳「插進去釘牢」地面、「站在原地不退讓」堅守自己想法。\n\n記憶畫面：點火鍋到底要不要加芋頭，他雙手護住湯鍋雙腳「插進去釘牢」「站在原地不退讓」說一定要煮爛才好吃，這副態度真是太堅持主張 (insist) 了！",
  "insistence": "字根幽默拆解法：insist（堅持到底不退讓）＋ ence（名詞態度）\n\n構造聯想：insistence 就是好朋友說請客我來出、兩人搶帳單「堅持到底不退讓」的那份固執「態度」。\n\n記憶畫面：結帳時兩位長輩在櫃檯前推來推去搶著付錢誰都不讓，最後拗不過阿姨那份「堅持到底不退讓」的熱情「態度」只好乖乖收下，這就是堅持要求主張 (insistence)！",
  "insoluble": "字根幽默拆解法：in（不） ＋ soluble（可溶的）\n\n構造聯想：將 in（不） ＋ soluble（可溶的） 結合在一起，就能輕鬆推導出「不能解決的」的意思。\n\n記憶畫面：這塊物質在水中不能解決的 (insoluble)，完全無法溶解，沉在杯底。",
  "inspect": "字根幽默拆解法：in（湊近往裡面仔細瞧）＋ spect（睜大眼睛認真看）\n\n構造聯想：inspect 就是品質檢驗員拿著放大鏡「湊近往裡面仔細瞧」每顆蘋果，再「睜大眼睛認真看」有沒有瑕疵！\n\n記憶畫面：餅乾工廠出貨前品管師戴上白手套和放大鏡「湊近往裡面仔細瞧」每一盒餅乾重量，還要「睜大眼睛認真看」包裝有沒有密封，認真進行檢查審查審視 (inspect)！",
  "inspection": "字根幽默拆解法：in（往裡面看）＋ spect（仔細檢查）＋ ion（行動）\n\n構造聯想：inspection 就是拿手電筒照進每個角落「往裡面看」「仔細檢查」的嚴格「行動」。\n\n記憶畫面：衛生檢查員走進中央廚房，戴白手套到處「往裡面看」「仔細檢查」有沒有灰塵這趟「行動」，就叫做仔細的檢查與視察 (inspection)！",
  "inspector": "字根幽默拆解法：inspect（仔細檢查查案）＋ or（專業人員）\n\n構造聯想：inspector 就是胸前掛著證件走進工廠到處「仔細檢查」的「專業人員」。\n\n記憶畫面：拿著紀錄本和放大鏡在學校餐廳「仔細檢查」整潔衛生的這位「專業人員」，大家一看見他就趕快站直敬禮，他正是檢查員督察員 (inspector)！",
  "inspiration": "字根幽默拆解法：in（吹進腦門）＋ spir（靈魂氣息）＋ ation（火花）\n\n構造聯想：inspiration 就是洗澡時突然「吹進腦門」那道「靈魂氣息」閃現「火花」。\n\n記憶畫面：盯著空白畫布發呆兩小時沒頭緒，突然看見窗邊小貓伸懶腰那瞬間「吹進腦門」靈光一閃的「靈魂氣息」「火花」，這正是超棒靈感與好主意 (inspiration)！",
  "inspirational": "字根幽默拆解法：in（進入） ＋ spirit（靈魂精神）\n\n構造聯想：源自 inspire（啟發），spirit 是靈魂。\n\n記憶畫面：從「進入」的概念延伸，這場演講真是啟發靈感的 (inspirational)，聽完後我覺得渾身充滿力量，想去追逐夢想。",
  "inspire": "字根幽默拆解法：in（吹進去）＋ spire（元氣滿滿的氣息）\n\n構造聯想：inspire 就是偶像說了一句超熱血的話，把「元氣滿滿的氣息」「吹進去」你的心坎裡。\n\n記憶畫面：聽完學長從倒數考進理想科系的真實故事，好像有一股「元氣滿滿的氣息」被「吹進去」全身立刻熱血起來，真的非常鼓舞激勵人心 (inspire)！",
  "inspiring": "幽默諧音法：「硬斯派林」\n\n發音聯想：inspiring [͵ɪnˋspaɪrɪŋ] 唸起來就像「硬斯派林」。\n\n記憶畫面：這部電影的劇情太激勵人心 (inspiring)，讓人看完覺得硬斯（即使斯）也要拼一把。",
  "install": "幽默諧音法：「硬塞套」\n\n發音聯想：install 唸起來有點接近「硬塞套」。\n\n記憶畫面：新買的冷氣又重又大台，師傅一邊擦汗一邊把粗管線「硬」「塞」「套」進牆壁預留孔裡，總算順利安裝設置 (install) 好！",
  "installation": "字根幽默拆解法：install（裝上去設定好）＋ ation（完成過程與設備）\n\n構造聯想：installation 就是師傅敲敲打打把冷氣或軟體「裝上去設定好」後的整個「設備」。\n\n記憶畫面：新買的藝術大吊燈終於送到客廳，請專業師傅爬上梯子「裝上去設定好」點亮全屋這整套「設備」與手續，就是安裝設定與設施裝置 (installation)！",
  "installment": "字根幽默拆解法：in（照時間放進去）＋ stall（一格一格攤位階段）＋ ment\n\n構造聯想：installment 就是把買筆電的大筆錢切成「一格一格」每個月慢慢「照時間放進去」付清。\n\n記憶畫面：看到四萬塊筆電好想買但現金不夠，店員笑著說可以分成十二個月「一格一格」「照時間放進去」輕鬆繳款，這就是最親切的分期付款與一期雜誌 (installment)！",
  "instalment": "幽默諧音法：「印斯偷門特」\n\n發音聯想：instalment [ɪnˋstɔlmənt] 唸起來就像「印斯偷門特」。\n\n記憶畫面：買這台電腦如果不夠錢，可以分期付款，每個月印一張單子去偷門特（繳費），直到付清為止，展現出「一期付款」 (instalment) 的畫面！",
  "instance": "字根幽默拆解法：in（拿出來擺在）＋ stance（現場面前）\n\n構造聯想：instance 就是講道理大家聽不懂時，直接挑一個具體故事「拿出來擺在」「現場面前」講給你聽。\n\n記憶畫面：為了讓大家聽懂什麼叫勤儉，媽媽立刻把爸爸補了十年的舊襪子「拿出來擺在」「現場面前」當範例，這活生生一幕就是例子例項 (instance)！",
  "instant": "幽默諧音法：「印斯坦特」\n\n發音聯想：instant [ˋɪnstənt] 唸起來就像「印斯坦特」。\n\n記憶畫面：腦海浮現「印斯坦特」的情境——半夜肚子餓懶得開火煮飯，拿出泡麵撕開調味包沖熱水一瞬間燙三分鐘立刻開吃，超迅速便利就是立刻的即食的與片刻瞬間 (instant)！",
  "instantaneously": "字根幽默拆解法：instant（立即） ＋ aneous（形容詞） ＋ ly（副詞）\n\n構造聯想：instant 指一瞬間，常見於速食麵 instant noodles。\n\n記憶畫面：從「立即 (instantaneously)」的概念延伸，魔術師一揮手，鴿子就瞬間出現了。",
  "instead": "字根幽默拆解法：in（放進原本那個空位）＋ stead（替換上來的替代位置）\n\n構造聯想：instead 就是本來想買珍奶卻賣完了，於是「放進原本那個空位」改拿一杯黑糖鮮奶補上「替換上來的替代位置」。\n\n記憶畫面：本來排好週六去爬山卻因為早上下雨，全家「放進原本那個空位」改去美術館看恐龍展補在「替換上來的替代位置」，原本計劃變了反而卻代替 (instead) 得超好玩！",
  "instinct": "幽默諧音法：「硬斯挺得」\n\n發音聯想：instinct [ˋɪnstɪŋkt] 唸起來就像「硬斯挺得」。\n\n記憶畫面：動物面對危險時，身體會硬斯挺得去對抗，這就是動物的生存本能 (instinct)。",
  "instinctive": "字根幽默拆解法：in（內在） ＋ stinct（刺衝動） ＋ ive（形容詞）\n\n構造聯想：stinct 字根源自刺，引申為內心的衝動，instinct 就是本能。\n\n記憶畫面：當球飛過來時，他本能地伸手去接，這是一種本能的 (instinctive) 的反應。",
  "institute": "幽默諧音法：「硬斯低頭」\n\n發音聯想：institute [ˋɪnstə͵tut] 唸起來就像「硬斯低頭」。\n\n記憶畫面：這間歷史悠久的研究所 (institute) 裡，學者們『硬斯低頭』苦讀古老文獻。",
  "institution": "字根幽默拆解法：in（建立在裡頭）＋ stitut（站穩設立）＋ ion（大型組織）\n\n構造聯想：institution 就是流傳百年「建立在裡頭」且穩穩「站穩設立」社會的「大型組織」或老規矩。\n\n記憶畫面：城市裡像圖書館、國立大學和歷史博物館這種歷久彌新、「建立在裡頭」深深「站穩設立」的「大型組織」，就是公共機構團體與重要制度 (institution)！",
  "instruct": "字根幽默拆解法：in（往裡塞）＋ struct（步驟藍圖）\n\n構造聯想：instruct 就是把完整「步驟藍圖」一步步「往裡塞」進學生腦袋。\n\n記憶畫面：烘焙老師拿著食譜把打發奶油的「步驟藍圖」清清楚楚「往裡塞」進學員腦裡，超細心地指導指示 (instruct) 每個動作！",
  "instruction": "字根幽默拆解法：instruct（步驟教清楚）＋ ion（整套講解內容）\n\n構造聯想：instruction 就是買來新桌遊或家電裡面附贈的那張「步驟教清楚」超級詳細「講解內容」。\n\n記憶畫面：買了三百片樂高積木不知道從哪拚起，趕快翻開盒裡「步驟教清楚」每頁圖解超白的「講解內容」跟著拚，這份指南就是教學與用法說明指示 (instruction)！",
  "instructor": "字根幽默拆解法：in（不） ＋ struct（建造） ＋ or（的人或物）\n\n構造聯想：將 in（不） ＋ struct（建造） ＋ or（的人或物） 結合在一起，就能輕鬆推導出「教練」的意思。\n\n記憶畫面：滑雪教練 (instructor) 在雪地裡硬斯抓著學員的滑雪卡，嚴格指導每一個動作。",
  "instrument": "字根幽默拆解法：in（手上拿著）＋ stru（組裝工具）＋ ment（器具）\n\n構造聯想：instrument 就是音樂家或醫生「手上拿著」用來演奏或測量的精密「組裝工具」。\n\n記憶畫面：交響樂團舞台上擺滿小提琴、薩克斯風跟大鼓，每位樂手都寶貝著「手上拿著」這件會唱歌的精巧「組裝工具」「器具」，就是樂器與專業儀器 (instrument)！",
  "instrumental": "字根幽默拆解法：instrument（工具樂器） ＋ al（形容詞）\n\n構造聯想：instrument 本意是工具，後來延伸為樂器。\n\n記憶畫面：他在這項計畫中起到了關鍵作用，就像一把好用的工具，展現出「有幫助的」 (instrumental) 的畫面！",
  "insufficiency": "字根幽默拆解法：in（不） ＋ sufficiency（充足）\n\n構造聯想：字根 suf-（在下面）+ fic（做），意指做的不夠多，導致不足。\n\n記憶畫面：醫生診斷後表示，這是心臟機能的不足 (insufficiency)，也就是功能不全。",
  "insufficient": "字根幽默拆解法：in（不） ＋ sufficient（足夠的）\n\n構造聯想：字首 in- 表否定，sufficient 源自 sufficere（滿足）。\n\n記憶畫面：從「足夠」的概念延伸，證據不充分 (insufficient)，法官無法判決，這場官司還要再審。",
  "insular": "字根幽默拆解法：in（在裡面） ＋ sula（島嶼）\n\n構造聯想：字根 insul- 就是島的意思，類似 insulate（絕緣，像島一樣隔開）。\n\n記憶畫面：從「在裡」的概念延伸，一個人住在與世隔絕的 (insular)孤島上，因為長期沒接觸外界，思想變得非常狹隘保守。",
  "insulate": "字根幽默拆解法：insult（侮辱） ＋ ate（使）\n\n構造聯想：將 insult（侮辱） ＋ ate（使） 結合在一起，就能輕鬆推導出「使隔熱」的意思。\n\n記憶畫面：為了讓房子隔熱，工人在牆壁裡塞滿了絕緣材料，手都累特了，展現出使隔熱 (insulate) 的畫面！",
  "insult": "幽默諧音法：「硬塞喔」\n\n發音聯想：insult [͵ɪnˋsʌlt] 唸起來就像「硬塞喔」。\n\n記憶畫面：主管把完全不合理的工作硬塞給下屬，這根本是在精神上侮辱 (insult)人。",
  "insurance": "幽默諧音法：「硬休朗熄」\n\n發音聯想：insurance [͵ɪnˋʃʊrəns] 唸起來就像「硬休朗熄」。\n\n記憶畫面：老闆說工作太累要硬休，朗讀保險 (insurance)單來讓心裡的焦慮平息。",
  "insure": "字根幽默拆解法：in（不） ＋ sure（確信的）\n\n構造聯想：將 in（不） ＋ sure（確信的） 結合在一起，就能輕鬆推導出「投保」的意思。\n\n記憶畫面：因秀兒因為是秀兒優秀的孩子，所以幫他買保險來確保 (insure) 安全。",
  "intact": "幽默諧音法：「印鐵克」\n\n發音聯想：intact [͵ɪnˋtækt] 唸起來就像「印鐵克」。\n\n記憶畫面：經過大地震後，這棟鐵克（特）建築依然完整無缺 (intact)、完好如初。",
  "integrate": "幽默諧音法：「因特格瑞」\n\n發音聯想：integrate [ˋɪntə͵ɡret] 唸起來就像「因特格瑞」。\n\n記憶畫面：「因特格瑞」——因為特別熱情（特格瑞），大家終於把不同派系成功結合為一體，展現出「使結合」 (integrate) 的畫面！",
  "integration": "幽默諧音法：「印踢個瑞遜」\n\n發音聯想：integration [͵ɪntəˋɡreʃən] 唸起來就像「印踢個瑞遜」。\n\n記憶畫面：「印踢個瑞遜」－把各國特色印在球上，大家一起踢個球來達到文化融合與整合 (integration)。",
  "integrity": "幽默諧音法：「印得格瑞替」\n\n發音聯想：integrity [͵ɪnˋtɛɡrəti] 唸起來就像「印得格瑞替」。\n\n記憶畫面：「印得格瑞替」－能夠把誠實正直 (integrity)的品格印在獎狀上得第一名，才是值得替他驕傲的表現。",
  "intellect": "幽默諧音法：「印特來客」\n\n發音聯想：intellect [ˋɪntə͵lɛkt] 唸起來就像「印特來客」。\n\n記憶畫面：「印特來客」－特別印製傳單來招攬高智力 (intellect)的聰明客人到店裡參觀。",
  "intellectual": "幽默諧音法：「印塔累可處」\n\n發音聯想：intellectual [͵ɪntəˋlɛktʃuəl] 唸起來就像「印塔累可處」。\n\n記憶畫面：順著「印塔累可處」的諧音去想：高知識分子 (intellectual) 坐在咖啡廳裡，印特力客地抓著筆記討論深奧的哲學問題。",
  "intelligence": "字根幽默拆解法：intel（敏銳挑出）＋ lig（理出重點）＋ ence（腦力）\n\n構造聯想：intelligence 就是讀書抓重點超快、總能從一堆題目裡「敏銳挑出」「理出重點」的超強「腦力」。\n\n記憶畫面：別人背課文背得滿頭汗，他卻三分鐘「敏銳挑出」關鍵脈絡輕鬆「理出重點」，這股聰明頭腦「腦力」正是智力智慧與機密情報 (intelligence)！",
  "intelligent": "幽默諧音法：「印特拉真特」\n\n發音聯想：intelligent [͵ɪnˋtɛlədʒənt] 唸起來就像「印特拉真特」。\n\n記憶畫面：聽到一聲「印特拉真特」，就看到硬台邏輯能停的頭腦非常有才智的 (intelligent) （聰明的、有才智的）。",
  "intelligibility": "字根幽默拆解法：intel（智力） ＋ lig（選擇讀） ＋ ibility（能力）\n\n構造聯想：源自 intelligent，指事物本身具備被理解的特質。\n\n記憶畫面：這台老舊收音機的聲音雜訊很大，嚴重影響了可理解性 (intelligibility)。",
  "intelligibly": "字根幽默拆解法：intelligible（可理解的） ＋ y（多的）\n\n構造聯想：由 intelligible（可理解的）去 e 加 y 變為副詞形 -ibly。\n\n記憶畫面：這個外國人用印表機印出很清楚的文件，讓人易理解地 (intelligibly)讀懂內容。",
  "intend": "字根幽默拆解法：in（心裡）＋ tend（伸展、朝向）\n\n構造聯想：intend 就是「心裡」已經默默「朝向」某件事打轉。\n\n記憶畫面：他站在櫥窗前「心裡」早就一路「朝向」那台新主機伸出手去，看來領薪水後就打算 (intend) 立刻抱回家！",
  "intense": "字根幽默拆解法：in（往內用力）＋ tense（拉緊繃住）\n\n構造聯想：intense 就是把弦「往內用力」「拉緊繃住」到差一點就彈開的程度。\n\n記憶畫面：拔河比賽倒數最後十秒，兩隊選手雙手「往內用力」把粗麻繩「拉緊繃住」寸土不讓，全場氣氛超級強烈劇烈 (intense)！",
  "intensification": "字根幽默拆解法：intense（強烈的） ＋ ification（化）\n\n構造聯想：intense 是強烈的，intensify 是動詞，轉為名詞。\n\n記憶畫面：由於雙方衝突的強化 (intensification)，談判桌上的氣氛變得異常緊張。",
  "intensify": "字根幽默拆解法：intense（強烈緊繃）＋ ify（使……加倍）\n\n構造聯想：intensify 就是把原本已經「強烈」的張力再「使」它「加倍」升溫。\n\n記憶畫面：球賽最後十秒兩隊剛好平手，全場加油鼓聲齊鳴「使」這股「強烈」緊張感往上「加倍」，讓勝負氣氛瞬間增強加劇 (intensify)！",
  "intensity": "幽默諧音法：「硬貼斯踢」\n\n發音聯想：intensity [ɪnˋtɛnsəti] 唸起來就像「硬貼斯踢」。\n\n記憶畫面：颱風天風雨強度 (intensity)太大，招牌硬貼在玻璃上被踢得粉碎。",
  "intensive": "字根幽默拆解法：intense（高度集中用力）＋ ive（的）\n\n構造聯想：intensive 就是考前一週把所有資源和時間「高度集中用力」「的」衝刺法。\n\n記憶畫面：語言營每天早中晚全英文對話不准講中文，那種把知識「高度集中用力」「的」塞滿腦袋的安排，就是超紮實的密集集中 (intensive) 特訓！",
  "intent": "字根幽默拆解法：in（不） ＋ tent（帳篷）\n\n構造聯想：將 in（不） ＋ tent（帳篷） 結合在一起，就能輕鬆推導出「專注的」的意思。\n\n記憶畫面：警官『硬聽特』別人的對話，眼神極為專注 (intent)，充滿堅決的意味。",
  "intention": "字根幽默拆解法：in（不） ＋ ten（握住） ＋ tion（動作或狀態）\n\n構造聯想：將 in（不） ＋ ten（握住） ＋ tion（動作或狀態） 結合在一起，就能輕鬆推導出「意圖」的意思。\n\n記憶畫面：老闆推出這項優惠活動的真正意圖 (intention)，其實是為了硬貼心來賺取更多客源。",
  "interact": "字根幽默拆解法：inter（彼此之間）＋ act（行動回應）\n\n構造聯想：interact 就是你丟梗我接球，「彼此之間」熱絡地「行動回應」。\n\n記憶畫面：上課別只顧著低頭發呆，多和台上老師及旁邊同學「彼此之間」舉手拋接「行動回應」，課堂互動 (interact) 才有趣！",
  "interaction": "字根幽默拆解法：inter（互相） ＋ action（行動）\n\n構造聯想：inter- 字首代表「互相」，結合 action（行動），兩者互相行動就是互動。\n\n記憶畫面：從「互相」的概念延伸，老師在課堂上透過問答與學生進行熱烈的互動 (interaction)交流。",
  "interactive": "字根幽默拆解法：inter（互相） ＋ act（行動）\n\n構造聯想：inter 是常見字首，表示在兩者之間。\n\n記憶畫面：從「互相」的概念延伸，這款互動 (interactive)式遊戲讓玩家能與螢幕裡的角色進行即時對話。",
  "interchange": "字根幽默拆解法：inter（在） ＋ change（改變）\n\n構造聯想：字首 inter 代表在...之間，change 代表改變，兩者結合為交換。\n\n記憶畫面：從「改變」的概念延伸，兩個國家的留學生在寒假期間互相交換 (interchange)禮物與文化心得。",
  "interchangeable": "字根幽默拆解法：inter（互相） ＋ change（交換） ＋ able（可的）\n\n構造聯想：inter 字首表示在兩者之間。\n\n記憶畫面：從「互相」的概念延伸，這兩款螺絲規格一樣，是完全可互換的 (interchangeable)。",
  "interest": "字根幽默拆解法：inter（心神跑進去裡面）＋ est（產生最濃厚的連結）\n\n構造聯想：interest 就是看到喜歡的樂器或天文圖鑑時整個人「心神跑進去裡面」，與事物「產生最濃厚的連結」進而想研究，也指銀行放進本金多出的利息。\n\n記憶畫面：走進科學博物館看到會發光的太陽系模型後她「心神跑進去裡面」盯了半小時，跟宇宙奧秘「產生最濃厚的連結」點燃滿滿興趣關注 (interest)！",
  "interested": "字根幽默拆解法：interest（興趣） ＋ ed（過去分詞或形容詞）\n\n構造聯想：將 interest（興趣） ＋ ed（過去分詞或形容詞） 結合在一起，就能輕鬆推導出「感興趣的」的意思。\n\n記憶畫面：我對這本印著特殊圖案的書很感興趣 (interested)，一直盯著看。",
  "interesting": "字根幽默拆解法：interest（興趣） ＋ ing（動作或形容詞）\n\n構造聯想：將 interest（興趣） ＋ ing（動作或形容詞） 結合在一起，就能輕鬆推導出「有趣的」的意思。\n\n記憶畫面：這本書內容太有趣 (interesting)，印得累翻我也要聽完。",
  "interfere": "字根幽默拆解法：inter（插在中間）＋ fere（手伸進來）\n\n構造聯想：interfere 就是人家聊得正開心，偏要「插在中間」把「手伸進來」管。\n\n記憶畫面：兩個好友正在講悄悄話，旁邊愛湊熱鬧的人硬要「插在中間」把「手伸進來」指手畫腳，實在很愛干涉介入 (interfere)！",
  "interference": "字根幽默拆解法：inter（在之間） ＋ fer（拿） ＋ ence（狀態）\n\n構造聯想：將 inter（在之間） ＋ fer（拿） ＋ ence（狀態） 結合在一起，就能輕鬆推導出「干涉」的意思。\n\n記憶畫面：主管『硬替費人身』安全作過度干涉 (interference)，讓員工感到不舒服。",
  "interior": "幽默諧音法：「硬題理由」\n\n發音聯想：interior [͵ɪnˋtɪriɚ] 唸起來就像「硬題理由」。\n\n記憶畫面：設計師『硬題理由』來解釋房子內部的裝潢，強調車子內裝 (interior) 的質感。",
  "intermediate": "字根幽默拆解法：inter（中間） ＋ medi（中間） ＋ ate（形容詞）\n\n構造聯想：字根 medi 意為 middle（中間），夾在兩者中間的自然就是中級或調解人。\n\n記憶畫面：這隻鴨子剛好卡在河水的中間 (intermediate)，不上不下，處於中級水準的位置。",
  "intermingles": "幽默諧音法：「印特明嘎茲」\n\n發音聯想：intermingles [͵ɪntɚˋmɪŋɡəlz] 唸起來就像兩隊舞團「印特明嘎茲」交錯共舞。\n\n記憶畫面：爵士樂隊與民俗弦樂團走上同一個舞台，「印特明嘎茲」旋律自然交織，不同風格完美地相互混合與交融 (intermingles)！",
  "intermittent": "幽默諧音法：「硬特密特」\n\n發音聯想：intermittent [͵ɪntɚˋmɪtənt] 唸起來就像「硬特密特」。\n\n記憶畫面：這台收音機訊號斷斷續續 (intermittent)，聽起來硬特密特（很特密特，不清楚）。",
  "internal": "幽默諧音法：「印特拿」\n\n發音聯想：internal [͵ɪnˋtɝnəl] 唸起來就像「印特拿」。\n\n記憶畫面：腦海浮現「印特拿」的情境——公司進行內政改革，各部門內部 (internal) 都要重新調整。",
  "international": "字根幽默拆解法：inter（跨越之間）＋ nation（各個國家）＋ al（的）\n\n構造聯想：international 就是「跨越」國界線把「各個國家」連在一起的盛會。\n\n記憶畫面：奧運開幕式各國選手揮著國旗齊聚會場，「跨越」「各個國家」同場切磋運動實力，這才叫超級盛大的國際的 (international) 賽事！",
  "internationalize": "字根幽默拆解法：inter（國際） ＋ nation（國家） ＋ alize（使化）\n\n構造聯想：alize 是常見的動詞後綴，表示使成為。\n\n記憶畫面：這家公司決定將業務國際化，進軍全球市場，展現出「使國際化」 (internationalize) 的畫面！",
  "internet": "字根幽默拆解法：inter（互相國際） ＋ net（網子）\n\n構造聯想：inter 意為互相、網狀交織，net 就是網子，合起來就是網際網路。\n\n記憶畫面：全世界的電腦透過無形的網子互相連結，形成了龐大的網際網路 (Internet)。",
  "interpolated": "字根幽默拆解法：inter（在中間） ＋ pole（桿子）\n\n構造聯想：inter- 是常見字首，表示在兩者之間。\n\n記憶畫面：在兩根桿子中間硬塞進東西，這就是插入或補充，展現出「話語」 (interpolated) 的畫面！",
  "interpret": "字根幽默拆解法：inter（站兩者間）＋ pret（把話說清楚）\n\n構造聯想：interpret 就是「站兩者間」幫忙搭橋樑「把話說清楚」。\n\n記憶畫面：外國朋友跟夜市老闆比手畫腳點餐快投降，路過熱心學生立刻「站兩者間」「把話說清楚」點好珍珠奶茶，神級口譯解釋 (interpret) 拯救全場！",
  "interpretation": "字根幽默拆解法：interpret（解釋） ＋ ation（動作或過程）\n\n構造聯想：將 interpret（解釋） ＋ ation（動作或過程） 結合在一起，就能輕鬆推導出「解釋」的意思。\n\n記憶畫面：同傳譯員『硬挺頻律表單』上的專業術語，進行精準的口語解釋與闡明 (interpretation)。",
  "interpreter": "字根幽默拆解法：interpret（解釋） ＋ er（的人或物）\n\n構造聯想：將 interpret（解釋） ＋ er（的人或物） 結合在一起，就能輕鬆推導出「通譯員」的意思。\n\n記憶畫面：國際會議上，口譯員 (interpreter) 反應超快，『硬挺跑得快』地幫外賓即時翻譯。",
  "interrogate": "字根幽默拆解法：inter（在之間） ＋ rog（詢問） ＋ ate（使）\n\n構造聯想：將 inter（在之間） ＋ rog（詢問） ＋ ate（使） 結合在一起，就能輕鬆推導出「審問」的意思。\n\n記憶畫面：警察把犯人印特（特別）肉隔開特別審問 (interrogate)，嚴厲質問案發經過。",
  "interrogation": "字根幽默拆解法：inter（在之間） ＋ rog（詢問） ＋ ation（動作或過程）\n\n構造聯想：將 inter（在之間） ＋ rog（詢問） ＋ ation（動作或過程） 結合在一起，就能輕鬆推導出「審問」的意思。\n\n記憶畫面：審問 (interrogation) 室裡，音（in）量特別（ter）大的羅（ro）警官，蓋（ga）過嫌犯的聲音，遜（tion）色的是嫌犯完全答不上來。",
  "interrupt": "字根幽默拆解法：inter（在之間） ＋ rupt（斷裂）\n\n構造聯想：將 inter（在之間） ＋ rupt（斷裂） 結合在一起，就能輕鬆推導出「打斷」的意思。\n\n記憶畫面：大家正在開會，他卻硬要中途打斷 (interrupt) 大家的發言，然後繞跑。",
  "interruption": "字根幽默拆解法：interrupt（打斷） ＋ tion（動作或狀態）\n\n構造聯想：將 interrupt（打斷） ＋ tion（動作或狀態） 結合在一起，就能輕鬆推導出「中止」的意思。\n\n記憶畫面：主管正在開會時突然被電話打斷 (interruption)，導致大家瞬間軟腳、思緒跑神。",
  "intersection": "幽默諧音法：「印特色穴森」\n\n發音聯想：intersection [͵ɪntɚˋsɛkʃən] 唸起來就像「印特色穴森」。\n\n記憶畫面：「印特色穴森」－在具有地方特色的十字路口 (intersection)地上，印上可愛的動物穴居森林圖案。",
  "intertwined": "字根幽默拆解法：inter（互相） ＋ twine（纏繞）\n\n構造聯想：inter- 字首表示互相，twine 聯想雙胞胎 twin 纏在一起。\n\n記憶畫面：兩棵樹的枝幹互相纏繞 (intertwined)，就像這對戀人的命運一樣交織在一起。",
  "interval": "字根幽默拆解法：inter（在之間） ＋ val（價值）\n\n構造聯想：將 inter（在之間） ＋ val（價值） 結合在一起，就能輕鬆推導出「間隔」的意思。\n\n記憶畫面：印特挖歐－在兩首歌曲的中場休息間隔 (interval) 中，工作人員趕快印出特製挖洞的音箱並大喊歐。",
  "intervene": "字根幽默拆解法：inter（站到兩個人中間）＋ vene（走過來插進來）\n\n構造聯想：intervene 就是看兩位同學快吵起來時，趕快「站到兩個人中間」「走過來插進來」喊暫停勸架。\n\n記憶畫面：兩隻小貓為了搶紙箱快出爪子啦，主人趕快提著罐頭「站到兩個人中間」「走過來插進來」幫忙調停分開，這即時動作正是介入干預與調停 (intervene)！",
  "intervention": "字根幽默拆解法：inter（在之間） ＋ ven（來） ＋ tion（動作或狀態）\n\n構造聯想：將 inter（在之間） ＋ ven（來） ＋ tion（動作或狀態） 結合在一起，就能輕鬆推導出「介入」的意思。\n\n記憶畫面：印特餵森森－印出特效藥方來餵給森森吃，這是醫生及時的醫療介入 (intervention) 與干預。",
  "interview": "字根幽默拆解法：inter（互相） ＋ view（看）\n\n構造聯想：inter（互相）加上 view（看），雙方互相看相了解。\n\n記憶畫面：求職者穿西裝去公司參加主管的面試 (interview)。",
  "interviewee": "字根幽默拆解法：interview（面試） ＋ ee（受詞人）\n\n構造聯想：ee 結尾通常指被動接受動作的人，如 employee（被雇用者）。\n\n記憶畫面：面試官坐在對面，而我是那位緊張的被面試者，展現出「被面試的人」 (interviewee) 的畫面！",
  "interviewer": "字根幽默拆解法：inter（在之間） ＋ viewer（觀看者）\n\n構造聯想：將 inter（在之間） ＋ viewer（觀看者） 結合在一起，就能輕鬆推導出「採訪者」的意思。\n\n記憶畫面：面試官 (interviewer) 坐在桌子對面，手裡印著特製的履歷表，正在仔細觀看（view）應徵者。",
  "intimacy": "幽默諧音法：「印踏嘛細」\n\n發音聯想：intimacy [ˋɪntəməsi] 唸起來就像「印踏嘛細」。\n\n記憶畫面：「印踏嘛細」－情侶兩人踩著腳踏車緊緊相依，感情親密 (intimacy)得像是一家人沒什麼好細分計較的。",
  "intimate": "幽默諧音法：「印太密特」\n\n發音聯想：intimate [ˋɪntəmət] 唸起來就像「印太密特」。\n\n記憶畫面：兩位好朋友在印太地區的祕密特區裡，分享彼此最私密的個人 (intimate)心事。",
  "intimidate": "字根幽默拆解法：in（塞進心裡）＋ timid（膽小怕怕）＋ ate（使他感到）\n\n構造聯想：intimidate 就是大塊頭故意皺眉跺腳把「膽小怕怕」的緊張感硬「塞進心裡」「使他感到」壓力。\n\n記憶畫面：比賽前對手隊長故意走過來冷笑放狠話想把「膽小怕怕」念頭「塞進心裡」「使他感到」動搖，結果我們淡定一笑沒被這招威嚇恫嚇 (intimidate) 成功！",
  "into": "字根幽默拆解法：in（往內）＋ to（到達）\n\n構造聯想：into 就是從外頭一路「往內」「到達」裡面，代表進入、到…裡面。\n\n記憶畫面：小兔子蹦蹦跳跳「往內」「到達」樹洞深處，鑽進入 (into) 溫暖的窩裡！",
  "intolerance": "字根幽默拆解法：in（不） ＋ tolerance（容忍）\n\n構造聯想：tolerance 是容忍，加上 in- 變成否定，就是無法忍受。\n\n記憶畫面：從「容忍」的概念延伸，他對別人的遲到完全無法忍受，表現出極度的不寬容 (intolerance)。",
  "intonation": "字根幽默拆解法：in（加進去）＋ ton（聲音高低音調）＋ ation（講話起伏）\n\n構造聯想：intonation 就是講英文問句結尾往上揚、感嘆往下降的那種「加進去」「聲音高低音調」起伏感。\n\n記憶畫面：機器人唸課文每個字都平平的沒感情，老師教大家說話要「加進去」「聲音高低音調」的生動「講話起伏」，語氣才會好聽有語調抑揚頓挫 (intonation)！",
  "intone": "字根幽默拆解法：in（進入） ＋ tone（語調）\n\n構造聯想：字首 in 進入 + tone 語調，合起來指用特定的音調吟誦。\n\n記憶畫面：神父在莊嚴的教堂內，緩慢地吟誦 (intone)著聖經經文。",
  "intransigence": "幽默諧音法：「印特然茲真」\n\n發音聯想：intransigence [ɪnˋtrænzɪdʒəns] 唸起來就像「印特然茲真」。\n\n記憶畫面：順著「印特然茲真」的諧音去想：談判桌上，他那種不妥協 (intransigence) 的態度讓雙方陷入了僵局，簡直像斯人一樣僵硬。",
  "intrepid": "幽默諧音法：「印特瑞批的」\n\n發音聯想：intrepid [ɪnˋtrepɪd] 唸起來就像「印特瑞批的」。\n\n記憶畫面：聽到一聲「印特瑞批的」，就看到印地安登山客無畏的 (intrepid) 地深入神祕的原始雨林。",
  "intricacy": "幽默諧音法：「印取卡細」\n\n發音聯想：intricacy [ˋɪntrɪkəsi] 唸起來就像「印取卡細」。\n\n記憶畫面：這張地圖的印刷細節太複雜了，連卡片上的紋路都細緻到看不清楚，展現出「錯綜複雜的事物」 (intricacy) 的畫面！",
  "intricate": "字根幽默拆解法：in（在裡面） ＋ trick（詭計） ＋ ate（吃）\n\n構造聯想：字根 intric- 源自拉丁語，意指糾纏不清，聯想複雜的線團。\n\n記憶畫面：這座迷宮設計得太複雜，像是在裡面藏了詭計，讓人走進去就想吃掉腦細胞，展現出「錯綜複雜的」 (intricate) 的畫面！",
  "introduce": "字根幽默拆解法：intro（往圈子裡面）＋ duce（牽著帶來見面）\n\n構造聯想：introduce 就是派對上牽著害羞新朋友的手「往圈子裡面」「牽著帶來見面」讓大家認識。\n\n記憶畫面：轉學生第一天站上講台有點緊張，班長熱情走過去「往圈子裡面」「牽著帶來見面」喊出他最愛打球跟喝珍奶，瞬間破冰成功完成自我介紹引見 (introduce)！",
  "introduced": "字根幽默拆解法：introduce（介紹） ＋ ed（過去分詞或形容詞）\n\n構造聯想：將 introduce（介紹） ＋ ed（過去分詞或形容詞） 結合在一起，就能輕鬆推導出「介紹」的意思。\n\n記憶畫面：派對上，朋友把新認識的對象介紹 (introduced) 給我，那種尷尬又興奮的氣氛吹入了心房。",
  "introduction": "字根幽默拆解法：introduce（介紹） ＋ tion（動作或狀態）\n\n構造聯想：將 introduce（介紹） ＋ tion（動作或狀態） 結合在一起，就能輕鬆推導出「介紹」的意思。\n\n記憶畫面：因偷抓橘子遜所以老師在新學期開始時先做自我介紹 (introduction)！",
  "introductory": "字根幽默拆解法：intro（進入） ＋ duct（引導） ＋ ory（形容詞）\n\n構造聯想：字根 duct 代表引導，如 conduct（引導/行為），intro- 代表向內。\n\n記憶畫面：這是一本入門書，引導 (introductory)你進入知識的大門，是初學者的最佳導航。",
  "intrude": "幽默諧音法：「印特入的」\n\n發音聯想：intrude [͵ɪnˋtrud] 唸起來就像「印特入的」。\n\n記憶畫面：聽到一聲「印特入的」，就看到深夜時分，一名陌生男子怪神祕祟地闖入 (intrude) 私人住宅行竊。",
  "intruder": "幽默諧音法：「音阻打」\n\n發音聯想：intruder [͵ɪnˋtrudɚ] 唸起來就像「音阻打」。\n\n記憶畫面：半夜小偷潛入家裡發出怪聲，屋主聽到奇怪的音阻打聲，立刻發現有侵入者 (intruder)闖進來。",
  "intrusion": "幽默諧音法：「印特入然」\n\n發音聯想：intrusion [ɪnˋtruʒ(ə)n] 唸起來就像「印特入然」。\n\n記憶畫面：聽到一聲「印特入然」，就看到小偷硬踹門闖入屋內，這是一種嚴重的侵犯 (intrusion) 隱私行為。",
  "intuition": "字根幽默拆解法：in（不） ＋ tuition（學費）\n\n構造聯想：將 in（不） ＋ tuition（學費） 結合在一起，就能輕鬆推導出「直覺」的意思。\n\n記憶畫面：警官憑著強大的直覺 (intuition)，『硬透伊秀身』的偽裝，一眼看出兇手是誰。",
  "inured": "字根幽默拆解法：in（進入） ＋ ure（使習慣） ＋ ed（……的）\n\n構造聯想：長久處在艱難環境「裡」漸漸「習慣」，就是「已習慣的」。\n\n記憶畫面：在喧鬧夜市旁住滿十年後，他早已徹底適應車水馬龍的噪音，對這種環境變得已習慣的 (inured)！",
  "invade": "幽默諧音法：「硬威得」\n\n發音聯想：invade [͵ɪnˋved] 唸起來就像「硬威得」。\n\n記憶畫面：「硬威得」靠著強硬的武力與威脅，外敵順利侵略 (invade)並攻佔了邊境城池。",
  "invalid": "字根幽默拆解法：in（不） ＋ valid（有效的）\n\n構造聯想：in（不）+ valid（有效的），指失去效力或健康。\n\n記憶畫面：因為簽名不符，這張支票被判定為無效的 (invalid)，無法兌現。",
  "invaluable": "字根幽默拆解法：in（不） ＋ valuable（有價值的）\n\n構造聯想：將 in（不） ＋ valuable（有價值的） 結合在一起，就能輕鬆推導出「非常貴重的」的意思。\n\n記憶畫面：老闆拿出一張絕版古董印花，強調它價值連城，是無價 (invaluable) 之寶。",
  "invasion": "字根幽默拆解法：invade（入侵） ＋ sion（動作或狀態）\n\n構造聯想：由動詞 invade（入侵）去 e 加 sion 轉變為名詞，指大舉進入或侵略。\n\n記憶畫面：敵軍為了攻佔這尊大砲，大舉進行殘酷的軍事入侵 (invasion)與侵略。",
  "invent": "幽默諧音法：「硬玩的」\n\n發音聯想：invent [͵ɪnˋvɛnt] 唸起來就像「硬玩的」。\n\n記憶畫面：「硬玩的」各種小道具，最後竟然發明 (invent)了電燈。",
  "invention": "字根幽默拆解法：in（不） ＋ ven（來） ＋ tion（動作或狀態）\n\n構造聯想：將 in（不） ＋ ven（來） ＋ tion（動作或狀態） 結合在一起，就能輕鬆推導出「發明」的意思。\n\n記憶畫面：神仙本來不用做事，但師傅硬是要挖出一個仙人來幫忙申請專利，展現出發明 (invention) 的畫面！",
  "inventive": "字根幽默拆解法：in（進入） ＋ vent（通風口） ＋ ive（形容詞）\n\n構造聯想：來自動詞 invent（發明），字根 vent 源自拉丁語 venire（來），意指創意來到腦中。\n\n記憶畫面：師傅在房間裡想出新點子，像是在悶熱中打開了通風口，創意源源不絕，展現出「發明的」 (inventive) 的畫面！",
  "inventor": "字根幽默拆解法：in（腦袋裡頭）＋ vent（冒出來新東西）＋ or（創作者）\n\n構造聯想：inventor 就是「腦袋裡頭」常常咻一聲「冒出來新東西」把怪點子做成實物的點子「創作者」。\n\n記憶畫面：嫌走路太累於是「腦袋裡頭」「冒出來新東西」做出電動滑板車還拿去申請專利，這位天天搞實驗的神級點子「創作者」正是發明家發明者 (inventor)！",
  "inventory": "幽默諧音法：「印分透麗」\n\n發音聯想：inventory [͵ɪnvənˋtɔri] 唸起來就像「印分透麗」。\n\n記憶畫面：倉庫管理員把所有貨物印成詳細清單 (inventory)，每一項都分得清清楚楚且透明利落。",
  "invest": "幽默諧音法：「硬微濕」\n\n發音聯想：invest [͵ɪnˋvɛst] 唸起來就像「硬微濕」。\n\n記憶畫面：「硬微濕」為了賺錢把剛領到的薪水全拿去投資 (invest)虛擬貨幣，緊張到手心都冒汗微濕了。",
  "investigate": "字根幽默拆解法：in（走進問題深處裡面）＋ vestig（追尋地上留下的腳印線索）＋ ate（動手展開詳細動作）\n\n構造聯想：investigate 就是像福爾摩斯一樣「走進問題深處裡面」，順著小碎餅乾屑「追尋地上留下的腳印線索」並「動手展開詳細動作」查明真相！\n\n記憶畫面：廚房少了一塊現烤蜂蜜鬆餅，家裡小偵探哥哥蹲在地毯上「走進問題深處裡面」，一路「追尋地上留下的腳印線索」直到「動手展開詳細動作」發現小貓窩旁有奶油痕跡，完美完成調查研究 (investigate)！",
  "investigation": "字根幽默拆解法：in（走進裡面）＋ vestig（追尋鞋印線索）＋ ation（查案行動）\n\n構造聯想：investigation 就是拿著放大鏡低頭「走進裡面」一步一步「追尋鞋印線索」到底怎麼回事。\n\n記憶畫面：班費盒少了一張百元鈔後大家扮小偵探，「走進裡面」教室「追尋鞋印線索」最後發現竟掉在掃把櫃後面，這場細心「查案行動」正是調查審查 (investigation)！",
  "investigator": "字根幽默拆解法：investigate（調查） ＋ or（的人或物）\n\n構造聯想：將 investigate（調查） ＋ or（的人或物） 結合在一起，就能輕鬆推導出「調查者」的意思。\n\n記憶畫面：警官硬是要把倒下小弟的案情蓋布挖出來，這位調查者 (investigator) 終於查清真相。",
  "investment": "幽默諧音法：「硬餵斯馬嗎」\n\n發音聯想：investment [͵ɪnˋvɛstmənt] 唸起來就像「硬餵斯馬嗎」。\n\n記憶畫面：這檔股票慘跌像斯馬一樣，你還要硬餵資金進去投資 (investment)嗎。",
  "investor": "幽默諧音法：「印位斯透」\n\n發音聯想：investor [͵ɪnˋvɛstɚ] 唸起來就像「印位斯透」。\n\n記憶畫面：投資者 (investor)把錢投進去，如果眼光不好，錢就像印出來的鈔票位子斯透了，血本無歸。",
  "invisible": "字根幽默拆解法：in（不） ＋ visible（可見的）\n\n構造聯想：字根 vis 代表看，如 vision（視覺），in- 是否定字首。\n\n記憶畫面：從「可見」的概念延伸，哈利波特的隱形斗篷，穿上後整個人變得看不見 (invisible)，完全隱形了。",
  "invitation": "字根幽默拆解法：in（不） ＋ vit（生命） ＋ ation（動作或過程）\n\n構造聯想：由動詞 invite（邀請）變化而來的名詞字尾 tion。\n\n記憶畫面：收到一張精美的結婚喜帖邀請函 (invitation)。",
  "invite": "幽默諧音法：「印外特」\n\n發音聯想：invite [͵ɪnˋvaɪt] 唸起來就像「印外特」。\n\n記憶畫面：聽到一聲「印外特」，就看到你硬要開一個大型派對，所以瘋狂地邀請 (invite) （邀請）朋友來家裡狂歡。",
  "invoice": "字根幽默拆解法：in（不） ＋ voice（聲音）\n\n構造聯想：源自法語 envoier（發送），意指發送給客戶的帳單。\n\n記憶畫面：收到請款單時，心裡發出哀號的聲音，這張紙就是提醒你要付錢的發票 (invoice)。",
  "invoke": "幽默諧音法：「印佛烏客」\n\n發音聯想：invoke [ɪnˋvoʊk] 唸起來就像「印佛烏客」。\n\n記憶畫面：聯想到「印佛烏客」的畫面：因我卡在法律漏洞，律師決定援引 (invoke) 法條來辯護。",
  "involve": "幽默諧音法：「因瓦爐」\n\n發音聯想：involve [͵ɪnˋvɑlv] 唸起來就像「因瓦爐」。\n\n記憶畫面：「因瓦爐」爆炸起火，導致整條街的住戶都被捲入這場公安意外中，展現出「使捲入」 (involve) 的畫面！",
  "involvement": "幽默諧音法：「硬挖不完的」\n\n發音聯想：involvement [͵ɪnˋvɑlvmənt] 唸起來就像「硬挖不完的」。\n\n記憶畫面：他深陷黑幫官司，這場介入 (involvement)和參與真是硬挖都挖不完的麻煩。",
  "inward": "字根幽默拆解法：in（裡面） ＋ ward（方向）\n\n構造聯想：由 in（裡面）加上 ward（方向字尾）組成，常指心靈或實體內部。\n\n記憶畫面：他深呼吸一口氣，把空氣向內 (inward)引導到肺部深處。",
  "inwards": "字根幽默拆解法：inward（向內） ＋ s（複數或動詞）\n\n構造聯想：將 inward（向內） ＋ s（複數或動詞） 結合在一起，就能輕鬆推導出「向內」的意思。\n\n記憶畫面：和尚為了尋找地底深處的古文物，正拿著工具朝地底硬挖的寺廟內心深處探索，展現出向內 (inwards) 的畫面！",
  "irate": "字根幽默拆解法：ir（不） ＋ ate（吃）\n\n構造聯想：將 ir（不） ＋ ate（吃） 結合在一起，就能輕鬆推導出「生氣的」的意思。\n\n記憶畫面：男友遲到太久，愛瑞特（愛生氣的 (irate) 瑞特）氣得七竅生煙大發雷霆。",
  "iron": "幽默諧音法：「愛恩」\n\n發音聯想：iron [ˋaɪɚn]（r 不捲舌時像愛恩）唸起來像「愛恩」。\n\n記憶畫面：媽媽充滿「愛恩」地拿起熱熨斗，把堅硬如鋼鐵 (iron) 般皺巴巴的襯衫燙得平平整整！",
  "ironic": "字根幽默拆解法：iron（鐵） ＋ ic（的）\n\n構造聯想：將 iron（鐵） ＋ ic（的） 結合在一起，就能輕鬆推導出「具有諷刺意味的」的意思。\n\n記憶畫面：剛剛才自信滿滿吹牛說自己從沒忘帶鑰匙，結果下一秒就被反鎖在門外，老天爺真愛鬧你虧人，場面有夠諷刺 (ironic)！",
  "irons": "字根幽默拆解法：iron（鐵） ＋ s（複數或動詞）\n\n構造聯想：iron 的複數形，複數用法常特指鐵製刑具或熨斗群。\n\n記憶畫面：從「複數」的概念延伸，媽媽一邊用蒸氣熨斗 (irons)燙衣服，一邊看電視。",
  "irony": "幽默諧音法：「愛惹你」\n\n發音聯想：irony [ˋaɪrəni] 唸起來就像「愛惹你」。\n\n記憶畫面：天兵男友總愛惹你生氣，結果自己卻先滑倒，這種出乎意料的結果真是莫大的諷刺 (irony)。",
  "irregular": "字根幽默拆解法：ir（不） ＋ regular（規則的）\n\n構造聯想：字首 ir 代表否定，regular 是規則，合起來就是不規則。\n\n記憶畫面：這塊地磚鋪得凹凸不平，完全不符合規則，看起來非常不平整的 (irregular)。",
  "irrelevant": "字根幽默拆解法：ir（不） ＋ relevant（相關的）\n\n構造聯想：「不」「相干」的離題內容，就是不相干的、無關的 (irrelevant)。\n\n記憶畫面：寫期末報告他竟大聊昨晚吃的宵夜有多美味，這些與主題完全「不」「相關」的廢話就是徹底不相干的 (irrelevant)！",
  "irreplaceable": "字根幽默拆解法：ir（不） ＋ replace（取代） ＋ able（能）\n\n構造聯想：字首 ir 表示否定，replace 是取代。\n\n記憶畫面：你在我心中是不可替代的 (irreplaceable)。",
  "irresolute": "字根幽默拆解法：ir（不） ＋ resolute（堅決）\n\n構造聯想：resolute 是堅決的，加上否定字首 ir-，變成猶豫不決。\n\n記憶畫面：站在十字路口，他優柔寡斷地 (irresolute) 看著地圖，遲遲無法決定往哪走。",
  "irritable": "幽默諧音法：「一熱踏波流」\n\n發音聯想：irritable [ˋɪrətəbəl] 唸起來就像「一熱踏波流」。\n\n記憶畫面：「一熱踏波流」聯想。天氣一熱大家腳步浮躁，變得非常易怒 (irritable)。",
  "irritate": "幽默諧音法：「伊瑞特特」\n\n發音聯想：irritate [ˋɪrɪ͵tet] 唸起來就像「伊瑞特特」。\n\n記憶畫面：聯想到「伊瑞特特」的畫面：一隻熱到發瘋的蝴蝶在耳邊嗡嗡叫，使人非常煩躁，展現出使惱怒 (irritate) 的畫面！",
  "irritated": "字根幽默拆解法：irritate（使惱怒） ＋ ed（過去分詞或形容詞）\n\n構造聯想：將 irritate（使惱怒） ＋ ed（過去分詞或形容詞） 結合在一起，就能輕鬆推導出「惱火的」的意思。\n\n記憶畫面：傷口被汗水浸濕一瑞特替得（一再覺得刺痛又發炎 (irritated) ）讓人奇癢無比。",
  "irritation": "字根幽默拆解法：irritate（使惱怒） ＋ tion（動作或狀態）\n\n構造聯想：將 irritate（使惱怒） ＋ tion（動作或狀態） 結合在一起，就能輕鬆推導出「激怒」的意思。\n\n記憶畫面：走路不小心踩到一粒小石子旋了一下腳踝，那種刺痛感讓人瞬間一肚子火、感到非常惱怒 (irritation)。",
  "is": "幽默諧音法：「意思」\n\n發音聯想：is [ɪz] 唸起來就像「意思」的前半音。\n\n記憶畫面：這句話的意思就是 (is) 祝大家今天事事順心！",
  "island": "幽默諧音法：「愛爾蘭的」\n\n發音聯想：island [ˋaɪlənd] 唸起來就像「愛爾蘭的」。\n\n記憶畫面：聽到一聲「愛爾蘭的」，就看到一隻海鷗飛過蔚藍海面上的美麗熱帶島嶼 (island)。",
  "isle": "幽默諧音法：「愛喔」\n\n發音聯想：isle [aɪl] 唸起來就像「愛喔」。\n\n記憶畫面：腦海浮現「愛喔」的情境——情侶『愛歐』奔向那座美麗的度假小島 (isle)，享受浪漫的二人世界。",
  "isolate": "幽默諧音法：「哀手累特」\n\n發音聯想：isolate [ˋaɪsə͵let] 唸起來就像「哀手累特」。\n\n記憶畫面：「哀手累特」確診後只能一個人被孤立 (isolate)在房間裡，手好累只能傳訊息哀號。",
  "isolation": "字根幽默拆解法：isolate（使孤立） ＋ tion（動作或狀態）\n\n構造聯想：將 isolate（使孤立） ＋ tion（動作或狀態） 結合在一起，就能輕鬆推導出「隔離」的意思。\n\n記憶畫面：確診被隔離 (isolation) 在房間裡，無聊到哀斯啦，溫度計看過去透零冷清。",
  "issue": "幽默諧音法：「硬秀」\n\n發音聯想：issue [ˋɪʃu] 唸起來就像「硬秀」。\n\n記憶畫面：政客在電視辯論會上『硬秀』各種社會爭論焦點與重要議題 (issue)。",
  "it": "幽默諧音法：「一踢」\n\n發音聯想：it [ɪt] 唸起來就像「一踢」。\n\n記憶畫面：看到地上有一顆球，隨便踢 (it) 它一腳。",
  "italics": "字根幽默拆解法：Italy（義大利） ＋ ics（學問字體）\n\n構造聯想：源自 Italy，因為這種字體最早由義大利印刷商開發。\n\n記憶畫面：義大利人寫字都喜歡歪歪斜斜的，所以這種斜體字就稱為義大利體 (italics)。",
  "italy": "幽默諧音法：「一塔力」\n\n發音聯想：italy [ˋɪtəli] 唸起來就像「一塔力」。\n\n記憶畫面：義大利的比薩斜塔很有名，只要去那裡，就能感受到「一塔力」的震撼，展現出「意大利」 (italy) 的畫面！",
  "itch": "幽默諧音法：「蟻去」\n\n發音聯想：itch [ɪtʃ] 唸起來就像「蟻去」。\n\n記憶畫面：身上爬滿螞蟻去咬你，導致皮膚一直發癢 (itch)想抓。",
  "item": "幽默諧音法：「愛坦」\n\n發音聯想：item [ˋaɪtəm] 唸起來就像「愛坦」。\n\n記憶畫面：聽到一聲「愛坦」，就看到購物車裡清清楚楚列著好幾項要買的商品項目 (item)。",
  "itemize": "字根幽默拆解法：item（項目） ＋ ize（動詞）\n\n構造聯想：item 原意為同樣地，後演變為清單中的每一項。\n\n記憶畫面：老闆要求把支出逐條列出，每一項都要寫清楚，這就是分條列述 (itemize) 的過程。",
  "itinerary": "幽默諧音法：「愛踢呢瑞」\n\n發音聯想：itinerary [aɪˋtɪnɚ͵ɛri] 唸起來就像「愛踢呢瑞」。\n\n記憶畫面：旅行社規劃的行程 (itinerary)表，上面寫著愛踢足球的瑞瑞要去哪裡玩。",
  "its": "幽默諧音法：「伊次」\n\n發音聯想：its [ɪts] 唸起來就像「伊次」。\n\n記憶畫面：聯想到「伊次」的畫面：這隻小狗搖著它的 (its) 尾巴。",
  "ivory": "幽默諧音法：「愛佛伊」\n\n發音聯想：ivory [ˋaɪvɚi] 唸起來就像「愛佛伊」。\n\n記憶畫面：腦海浮現「愛佛伊」的情境——大象無奈地嘆氣說唉我若有錢，就把珍貴的象牙 (ivory) 藏好，避免被盜獵者盯上。",
  "ivy": "幽默諧音法：「愛餵」\n\n發音聯想：ivy [ˋaɪvi] 唸起來就像「愛餵」。\n\n記憶畫面：牆上爬滿了綠色的常春藤 (ivy)，主人天天『愛餵』它水讓它長得茂盛。"
});
